def _scratch_pointer_apis(semsig_text: str) -> list:
    """WS3-110: intrinsics in a ``.semsig`` that expose the C-style caller-scratch
    contract — a raw ``OpaquePointer``/``Buffer`` arg PLUS a separate length/
    capacity scalar — to an app author without an ``unsafe yes`` marker. Returns the
    intrinsic names (sorted, deduped). Heuristic but conservative: it only fires when
    BOTH a raw pointer and a sizing scalar appear in the same intrinsic's arg list,
    which is exactly the unowned scratch-buffer shape the platform is graduating away
    from."""
    import re
    cap = re.compile(r"(?:capacity|length|bytes|size|cap|count)", re.I)
    found = []
    for block in re.split(r"\n(?=\S+ is intrinsic\b)", semsig_text):
        m = re.match(r"(\S+) is intrinsic", block)
        if not m:
            continue
        args = re.findall(r"\S+ (?:arg|out) (\w+) (\w+)", block)
        has_ptr = any(t in ("OpaquePointer", "Buffer") for _, t in args)
        has_cap = any(
            t not in ("OpaquePointer", "Buffer") and cap.search(slot)
            for slot, t in args
        )
        if has_ptr and has_cap and "unsafe yes" not in block:
            found.append(m.group(1))
    return sorted(set(found))


def _documentation_gaps(semsig_text: str) -> dict:
    """WS3-110 (`->test`): the ownership/error/description documentation an app
    author needs to use a public intrinsic safely. Returns the unambiguous gaps:

      * ``undocumented`` — intrinsics with no ``purpose`` row (no description at
        all); and
      * ``ownsWithoutCleanup`` — intrinsics that declare they ``own`` an output
        resource but never name its cleanup, either inline (``owns <slot> cleanedBy
        <target>``) or via a sibling ``<name> cleanedBy <target>`` row. An owned
        handle with no documented release is exactly the leak the ownership rows
        exist to prevent.

    Deliberately conservative — it does NOT flag a handle-returning intrinsic that
    omits ``owns`` entirely, because that legitimately marks a BORROWED return (a
    json child node, a cursor, a buffer slice, a memory view) whose lifetime is the
    parent's; demanding an ``owns`` row there would be a false positive."""
    import re
    undocumented, owns_without_cleanup = [], []
    for block in re.split(r"\n(?=\S+ is intrinsic\b)", semsig_text):
        m = re.match(r"(\S+) is intrinsic", block)
        if not m:
            continue
        name = m.group(1)
        if not re.search(rf"^{re.escape(name)} purpose ", block, re.M):
            undocumented.append(name)
        owns = re.findall(rf"^{re.escape(name)} owns (.+)$", block, re.M)
        if owns:
            inline = any("cleanedBy" in row for row in owns)
            sibling = bool(re.search(rf"^{re.escape(name)} cleanedBy ", block, re.M))
            if not inline and not sibling:
                owns_without_cleanup.append(name)
    return {"undocumented": sorted(set(undocumented)),
            "ownsWithoutCleanup": sorted(set(owns_without_cleanup))}


def stdlib_readiness_ledger() -> dict:
    """WS3-110: a generated readiness ledger classifying every `standard.*` module
    by maturity, derived from on-disk evidence so it cannot silently drift:

      * ``native``         — a ``native_<mod>/`` runtime dir or an ``ss_<mod>.c``
                             shim backs it;
      * ``lowered``        — a ``std/standard.<mod>.sem`` SemanticScript module;
      * ``intrinsic``      — the compiler lowers ``<mod>.*`` directly
                             (STDLIB_INTRINSIC_MODULES);
      * ``signature-only`` — a ``.semsig`` with none of the above, i.e. NO
                             implementation.

    A ``signature-only`` module that is not in EXPERIMENTAL_STDLIB_MODULES is a
    PUBLIC API with no backing — the gap the readiness gate catches: an app author
    would ``check`` clean and then fail at lower/run. Each entry records the
    ``status``, whether it is explicitly ``deferred`` (experimental), and the
    evidence flags (``semsig``/``lowered``)."""
    import os
    base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))  # semanticscript/
    sigs = os.path.join(base, "sigs")
    std = os.path.join(base, "std")
    rt = os.path.join(base, "runtime")
    modules: dict = {}

    def _scan(directory, suffix, key):
        if not os.path.isdir(directory):
            return
        for f in os.listdir(directory):
            if f.startswith("standard.") and f.endswith(suffix):
                modules.setdefault(f[len("standard."):-len(suffix)], {})[key] = True

    _scan(sigs, ".semsig", "semsig")
    _scan(std, ".sem", "lowered")
    native: set = set()
    if os.path.isdir(rt):
        for n in os.listdir(rt):
            if n.startswith("native_") and os.path.isdir(os.path.join(rt, n)):
                native.add(n[len("native_"):])
            elif n.startswith("ss_") and n.endswith(".c"):
                native.add(n[len("ss_"):-len(".c")])

    ledger: dict = {}
    for mod in sorted(modules):
        ev = modules[mod]
        if mod in native:
            status = "native"
        elif mod in STDLIB_INTRINSIC_MODULES:
            status = "intrinsic"
        elif ev.get("lowered"):
            status = "lowered"
        else:
            status = "signature-only"
        deferred = mod in EXPERIMENTAL_STDLIB_MODULES
        # WS3-110 (`->test`): parse this module's signature once to (a) inventory
        # the raw scratch-pointer contracts it exposes to app authors and (b) find
        # the ownership/error/description documentation gaps a public API must not
        # have.
        semsig_text = ""
        if ev.get("semsig"):
            try:
                with open(os.path.join(sigs, f"standard.{mod}.semsig"),
                          encoding="utf-8") as fh:
                    semsig_text = fh.read()
            except OSError:
                semsig_text = ""
        scratch = _scratch_pointer_apis(semsig_text) if semsig_text else []
        unack_scratch = bool(
            scratch and not deferred
            and mod not in STDLIB_SCRATCH_POINTER_ACKNOWLEDGED)
        docs = (_documentation_gaps(semsig_text) if semsig_text
                else {"undocumented": [], "ownsWithoutCleanup": []})
        # a public (non-deferred) module must fully document its intrinsics
        doc_gap = bool(
            not deferred
            and (docs["undocumented"] or docs["ownsWithoutCleanup"]))
        ledger[mod] = {
            "status": status,
            "deferred": deferred,
            # WS3-120: importance class (core vs nice-to-have), orthogonal to the
            # maturity classified above; carries no gate relief.
            "tier": "secondary" if mod in STDLIB_SECONDARY_MODULES else "core",
            "semsig": ev.get("semsig", False),
            "lowered": ev.get("lowered", False),
            # an unbacked public API: signature-only with no explicit deferral
            "unbackedPublic": status == "signature-only" and not deferred,
            # raw caller-scratch-buffer intrinsics this signature still exposes
            "scratchPointerApis": scratch,
            # ...that leak from a public module without acknowledgement (WS3-110)
            "unacknowledgedScratchPointer": unack_scratch,
            # intrinsics with no `purpose` description row
            "undocumentedApis": docs["undocumented"],
            # intrinsics that `own` an output but never name its cleanup
            "ownsWithoutCleanup": docs["ownsWithoutCleanup"],
            # ...either gap, in a public module the gate rejects (WS3-110)
            "documentationGap": doc_gap,
        }
    return ledger


def _stdlib_module_profile_evidence(module: str, ledger: dict) -> dict:
    entry = ledger.get(module)
    if entry is None:
        return {
            "status": "tracked-missing",
            "deferred": True,
            "semsig": False,
            "lowered": False,
            "unbackedPublic": False,
            "documentationGap": False,
            "scratchPointerApis": [],
        }
    return {
        "status": entry["status"],
        "deferred": entry["deferred"],
        "tier": entry["tier"],
        "semsig": entry["semsig"],
        "lowered": entry["lowered"],
        "unbackedPublic": entry["unbackedPublic"],
        "documentationGap": entry["documentationGap"],
        "scratchPointerApis": list(entry["scratchPointerApis"]),
        "unacknowledgedScratchPointer": entry["unacknowledgedScratchPointer"],
    }


def ws3_platform_profile() -> dict:
    """Generated WS3 platform roadmap/readiness profile.

    This keeps the broad WS3 standard-library rows tool-reachable: every row has
    a human title, the concrete modules that currently carry the work, acceptance
    gates, and generated ledger evidence. Missing future modules are explicit
    `tracked-missing` evidence rather than silent TODO prose.
    """
    ledger = stdlib_readiness_ledger()
    rows = []
    for spec in WS3_PLATFORM_PROFILE:
        evidence = {
            module: _stdlib_module_profile_evidence(module, ledger)
            for module in spec["modules"]
        }
        blockers = [
            module for module, item in evidence.items()
            if item["unbackedPublic"]
            or item["documentationGap"]
            or item.get("unacknowledgedScratchPointer", False)
        ]
        deferred = [
            module for module, item in evidence.items()
            if item["deferred"] or item["status"] == "tracked-missing"
        ]
        status = "ready-profiled"
        if blockers:
            status = "blocked"
        elif deferred:
            status = "profiled-with-deferred-modules"
        rows.append({
            "id": spec["id"],
            "title": spec["title"],
            "status": status,
            "modules": list(spec["modules"]),
            "acceptance": list(spec["acceptance"]),
            "evidence": evidence,
            "blockers": blockers,
            "deferredModules": deferred,
        })
    return {
        "status": "ok",
        "rows": rows,
        "ids": [row["id"] for row in rows],
    }

