def _new_project_files(name: str) -> dict:
    """The canonical `semanticscript new` skeleton (§28.2) as a {relpath: content} map."""
    pas = "".join(p[:1].upper() + p[1:] for p in __import__("re").split(r"[^A-Za-z0-9]+", name) if p) or "App"
    mod = pas[:1].lower() + pas[1:]
    main = (
        f"{mod} is module\n{mod} path src.main\n{mod} exports main\n"
        f'{mod} purpose "Entry module for {pas}"\n{mod} invariant "main is the only entry"\n\n'
        "ExitCode is alias\nExitCode for Int32\nExitCode purpose \"Process exit status\"\n\n"
        "stdoutWriter is capability\nstdoutWriter grants write console.stdout\n"
        'stdoutWriter purpose "Allow controlled stdout writes"\n\n'
        "main is operation\nmain out ExitCode\nmain effect write console.stdout\n"
        "main uses stdoutWriter\nmain async no\n"
        f'main purpose "Greet from {pas}"\nmain invariant "Writes one greeting line"\n'
        f'main let greeting immutable String "hello from {pas}"\n'
        "main let okCode immutable ExitCode 0\nmain do writeGreeting\nmain return okCode\n\n"
        "writeGreeting is call\nwriteGreeting in main\nwriteGreeting invokes console.writeLine\n"
        "writeGreeting arg text String greeting\n"
    )
    test = (
        f"{pas}Tests is project\n{pas}Tests module {mod}Tests\n{pas}Tests target console\n"
        f"{pas}Tests entry checkGreetingLength\n\n"
        f"{mod}Tests is module\n{mod}Tests path src.mainTest\n{mod}Tests exports checkGreetingLength\n"
        f'{mod}Tests purpose "Unit tests for {pas}"\n{mod}Tests invariant "All tag-test ops pass"\n\n'
        "ExitCode is alias\nExitCode for Int32\n\n"
        "checkGreetingLength is operation\ncheckGreetingLength out ExitCode\n"
        "checkGreetingLength async no\ncheckGreetingLength tag test\n"
        'checkGreetingLength purpose "Smoke test stub"\ncheckGreetingLength invariant "Returns 0"\n'
        "checkGreetingLength let pass immutable ExitCode 0\ncheckGreetingLength return pass\n"
    )
    build = (
        f"{pas} is project\n{pas} module {mod}\n{pas} target console\n{pas} entry main\n"
        f'{pas} languageVersion "1.0"\n{pas} toolchain "semanticscript"\n'
    )
    return {
        "build.sem": build,
        "src/main.sem": main,
        "src/main.test.sem": test,
        ".gitignore": "dist/\n",
        "tests/golden/.gitkeep": "",
    }


def cmd_new(args) -> int:
    """Scaffold a canonical EAV project tree (§28.2). R-005: refuse to clobber
    existing scaffold files unless `--force` — a mistyped path must not destroy
    an existing `build.sem`/`src/main.sem`. The collision list is reported in
    `sem.new.v1` so the failure is machine-readable, mirroring the §32.3 #20
    stale-file protection used by the patch loop."""
    import os
    root = args.path
    files = _new_project_files(os.path.basename(os.path.normpath(root)))
    collisions = sorted(
        rel for rel in files
        if os.path.exists(os.path.join(root, rel))
    )
    if collisions and not getattr(args, "force", False):
        sys.stdout.write(_json_envelope(
            "sem.new.v1", ok=False, status="collision", root=root,
            collisions=collisions, created=[],
            hint="pass --force to overwrite the listed files") + "\n")
        return 2
    created = []
    for rel, content in files.items():
        dest = os.path.join(root, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(content)
        created.append(rel)
    docs_index = None
    if getattr(args, "enable_docs_index", False):
        db_path = os.path.join(root, ".semanticscript", "docs.sqlite")
        docs_index = _docs_index_write(root, db_path)
        created.append(os.path.join(".semanticscript", "docs.sqlite"))
    sys.stdout.write(_json_envelope(
        "sem.new.v1", ok=True, status="created", root=root,
        created=sorted(created), overwritten=collisions,
        docsIndex=docs_index) + "\n")
    return 0


def cmd_task(args) -> int:
    """Emit an agent workflow checklist for a template (sem.task.v1)."""
    # TRUE-1 (R-15): `task` with no template lists the available templates (a
    # catalog), not an argparse error — a self-describing surface must answer
    # "what can I do?" instead of demanding an arg the caller is trying to learn.
    if getattr(args, "template", None) is None:
        sys.stdout.write(_json_envelope(
            "sem.task.v1", ok=True, status="catalog",
            templates=sorted(EAV_TASK_TEMPLATES),
            available=sorted(EAV_TASK_TEMPLATES)) + "\n")
        return 0
    tmpl = EAV_TASK_TEMPLATES.get(args.template)
    if tmpl is None:
        sys.stdout.write(_json_envelope(
            "sem.task.v1", ok=False,
            available=sorted(EAV_TASK_TEMPLATES)) + "\n")
        return 2
    sys.stdout.write(_json_envelope("sem.task.v1", template=args.template, **tmpl) + "\n")
    return 0


def cmd_mcp(args) -> int:
    """Run the MCP stdio JSON-RPC server (one request per line)."""
    import json
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            request = json.loads(line)
        except ValueError:
            # R-011: surface a JSON-RPC parse error instead of silently dropping
            # the line, so a malformed request is observable to the client.
            sys.stdout.write(json.dumps({
                "jsonrpc": "2.0", "id": None,
                "error": {"code": -32700, "message": "parse error"}}) + "\n")
            sys.stdout.flush()
            continue
        try:
            response = mcp_handle(request)
        except Exception as exc:  # R-125: a malformed frame must not kill the loop
            rid = request.get("id") if isinstance(request, dict) else None
            response = {"jsonrpc": "2.0", "id": rid, "error": {
                "code": -32603, "message": f"internal error: {exc}"}}
        if response is not None:  # R-111: notifications (no id) get no reply
            sys.stdout.write(json.dumps(response) + "\n")
            sys.stdout.flush()
    return 0


def cmd_version(args) -> int:
    """Emit the semanticscript contract version surface (sem.version.v1)."""
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope(
            "sem.version.v1", contractVersion=CONTRACT_VERSION, compiler="semanticscript",
            surfaces=list(SEM_SURFACES)) + "\n")
    else:
        sys.stdout.write(f"semanticscript {CONTRACT_VERSION}\n")
    return 0


def cmd_agent_docs(args) -> int:
    """Emit the version-matched EAV agent rules (sem.agentDocs.v1)."""
    sys.stdout.write(_json_envelope(
        "sem.agentDocs.v1", contractVersion=CONTRACT_VERSION,
        rules=EAV_AGENT_RULES) + "\n")
    return 0


def cmd_skills(args) -> int:
    """List EAV agent skills, or get full skill bodies by name (sem.skills.v1).

    `skills` with no names lists summaries; `skills <name>...` returns the full
    body for each named skill — the legacy list-vs-get contract."""
    names = getattr(args, "names", None)
    if names:
        items, missing = [], []
        for k in names:
            spec = EAV_SKILLS.get(k)
            if spec is not None:
                items.append({"name": k, "summary": spec["summary"],
                              "body": spec["body"]})
            else:
                missing.append(k)
        if missing:
            # R-121: a requested skill that doesn't exist is NOT an empty success —
            # an agent typo would otherwise proceed without the rule bundle it
            # asked for. Report it with the valid skill names.
            sys.stdout.write(_json_envelope(
                "sem.skills.v1", ok=False, status="not-found", skills=items,
                missing=missing, available=sorted(EAV_SKILLS)) + "\n")
            return 1
    else:
        items = [{"name": k, "summary": v["summary"]}
                 for k, v in EAV_SKILLS.items()]
    sys.stdout.write(_json_envelope("sem.skills.v1", skills=items) + "\n")
    return 0


_EVAL_SCAFFOLD = (
    "EvalProgram is project\nEvalProgram module evalModule\n"
    "EvalProgram target console\nEvalProgram entry main\n"
    "evalModule is module\nevalModule path eval.program\n"
    "evalModule exports main\nevalModule purpose \"Eval snippet\"\n"
    "evalModule invariant \"Runs the evaluated snippet\"\n"
    "ExitCode is alias\nExitCode for Int32\n"
)


def _source_declares_project(source_text: str) -> bool:
    """R-008: detect a real `<name> is project` entity row by lexing rows, not a
    raw substring search. Comments and string literals therefore cannot
    masquerade as a project declaration — `# … is project` is a comment row, and
    `"is project"` lexes to a single string token, not the `is`/`project`
    sequence."""
    if source_text.startswith("﻿"):
        source_text = source_text[1:]
    for raw in source_text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            tokens = tokenize_line(raw)
        except EavError:
            continue
        if len(tokens) >= 3 and tokens[1] == "is" and tokens[2] == "project":
            return True
    return False


def _parse_panic(stderr: str) -> Optional[dict]:
    """WS1-135: parse an `ss_panic` crash block out of captured stderr into a
    structured `panic` object for the sem.eval.v1 / run --json envelope. Returns
    None when the program did not trap through ss_panic."""
    import re
    m = re.search(r"EAV PANIC (SSR\d+) (\S+)", stderr)
    if not m:
        return None
    code, kind = m.group(1), m.group(2)

    def field(label):
        mm = re.search(label + r":[ \t]*(.+)", stderr)
        return mm.group(1).strip() if mm else None

    row = field("at line")
    operands = field("operands") or ""
    lm = re.search(r"left=(-?\d+)", operands)
    rm = re.search(r"right=(-?\d+)", operands)
    return {
        "code": code,
        "kind": kind,
        "op": field("op"),
        "row": int(row) if row and row.isdigit() else row,
        "reason": field("reason"),
        "operands": {
            "left": int(lm.group(1)) if lm else None,
            "right": int(rm.group(1)) if rm else None,
        },
    }


def _stdout_lines(out: str) -> list:
    """Split captured stdout into lines, dropping the single trailing element that
    a final newline produces. R-127: empty stdout is *no* lines (`[]`), not one
    blank line (`[""]`); a trailing newline does not add a phantom empty line."""
    lines = out.split("\n")
    return lines[:-1] if lines and lines[-1] == "" else lines


def _classify_run(out: str, err: str, code: int):
    """Map a captured (stdout, stderr, exitCode) run to a (status, panic) pair,
    shared by `eval --json` and `run --json` so the two surfaces never diverge."""
    if code == _EVAL_TIMEOUT_EXIT and "eval timeout" in err:
        return "timed-out", None  # R-101
    panic = _parse_panic(err)  # WS1-135
    if code == 0:
        status = "ok"
    elif panic is not None:
        status = "crashed"
    elif err.startswith("semanticscript:") or "\nsemanticscript:" in err:
        status = "compile-failed"  # parse/compile failure via main's EavError handler
    else:
        status = "nonzero-exit"
    return status, panic


def _unscaffold_lines(text: str, offset: int) -> str:
    """R-112: rewrite `line N` references in an eval snippet's diagnostics back
    from wrapped (scaffold-offset) coordinates to the user's snippet line numbers.
    Leaves a reference at or above the snippet boundary untouched if subtracting
    would underflow (a diagnostic genuinely in the scaffold prologue)."""
    import re
    if offset <= 0:
        return text

    def fix(m):
        n = int(m.group(1)) - offset
        return f"line {n}" if n >= 1 else m.group(0)

    return re.sub(r"\bline (\d+)", fix, text)


def cmd_eval(args) -> int:
    """Run a snippet through the JIT without scaffolding (sem.eval.v1): if the
    source declares no `project` entity, wrap it in a minimal console program,
    then JIT-run and return captured stdout/stderr + exit code and a status.

    R-008: project detection is lexical (not a substring), so a snippet whose
    comment or string text mentions `is project` still wraps and runs; and the
    payload carries stderr + a `status` so a compile failure is actionable
    instead of a bare `ok:false` with the diagnostic dropped.

    WS2-071: --strict blocks T3 warnings before running."""
    src = _read_source(args.path)
    wrapped = not _source_declares_project(src)
    # R-112: when the snippet is wrapped, the scaffold shifts every line number;
    # rewrite diagnostics/panic rows back to the user's snippet coordinates so an
    # editor or agent points its repair at the right line.
    offset = _EVAL_SCAFFOLD.count("\n") if wrapped else 0
    if wrapped:
        src = _EVAL_SCAFFOLD + src
    # WS2-071: --strict blocks T3 warnings
    if getattr(args, "strict", False):
        try:
            program = parse(src)
            diags = lint(program)
            diags = _filter_diagnostics_strict(diags, True)
            errors = [d for d in diags if d.severity == "error"]
            if errors:
                out, err = "", "\n".join(d.render() for d in errors)
                err = _unscaffold_lines(err, offset)
                code = 1
                status = "lint-error"
                sys.stdout.write(_json_envelope(
                    "sem.eval.v1", ok=False, status=status, exitCode=code, wrapped=wrapped,
                    stdout=out, stderr=err,
                    stdoutLines=[]) + "\n")
                return code  # R-100: ok:false exits nonzero
        except EavError:
            pass  # Fall through to _record_run_full which will catch the error
    out, err, code = _record_run_full(src)
    status, panic = _classify_run(out, err, code)
    if offset:
        err = _unscaffold_lines(err, offset)
        if panic is not None and isinstance(panic.get("row"), int):
            panic = {**panic, "row": panic["row"] - offset}
    payload = dict(
        ok=(code == 0), status=status, exitCode=code, wrapped=wrapped,
        stdout=out, stderr=err,
        stdoutLines=_stdout_lines(out))  # R-127
    if panic is not None:
        payload["panic"] = panic
    sys.stdout.write(_json_envelope("sem.eval.v1", **payload) + "\n")
    # R-100: process exit mirrors the program exit (0 iff ok); the program's
    # own exit code is preserved in the envelope's `exitCode` for the consumer.
    return code


def cmd_deps(args) -> int:
    """Dependency graph (sem.deps.v1): module imports + project require rows."""
    program = parse_compact(_read_program_source(args.path))
    imports, selective_imports, requires = [], [], []
    for n in program.order:
        ent = program.entities[n]
        if ent.kind == "module":
            import_paths = {
                r.payload[0]: (r.payload[1] if len(r.payload) > 1 else None)
                for r in ent.facts("imports")
                if r.payload
            }
            for r in ent.facts("imports"):
                if r.payload:
                    imports.append({"module": ent.name,
                                    "alias": r.payload[0],
                                    "path": r.payload[1] if len(r.payload) > 1 else None})
            for pred in _SELECTIVE_IMPORT_PREDICATES:
                kind = _SELECTIVE_IMPORT_KIND_BY_PREDICATE[pred]
                for r in ent.facts(pred):
                    if len(r.payload) >= 2:
                        selective_imports.append({
                            "module": ent.name,
                            "kind": kind,
                            "alias": r.payload[0],
                            "name": r.payload[1],
                            "path": import_paths.get(r.payload[0]),
                        })
        if ent.kind == "project":
            for r in ent.facts("require"):
                if r.payload:
                    requires.append({"path": r.payload[0],
                                     "version": r.payload[1] if len(r.payload) > 1 else None})
    sys.stdout.write(_json_envelope(
        "sem.deps.v1",
        imports=imports,
        selectiveImports=selective_imports,
        requires=requires,
    ) + "\n")
    return 0


def cmd_context(args) -> int:
    """Project envelope (sem.context.v1): target(s), entry, mode, modules."""
    program = parse_compact(_read_program_source(args.path))
    projects = program.of_kind("project")
    proj = projects[0] if projects else None

    def vals(ent, pred):
        return [r.payload[0] for r in ent.facts(pred) if r.payload]

    ctx = {
        "project": proj.name if proj else None,
        "targets": vals(proj, "target") if proj else [],
        "entry": (proj.fact("entry").payload[0]
                  if proj and proj.fact("entry") and proj.fact("entry").payload else None),
        "mode": (proj.fact("mode").payload[0]
                 if proj and proj.fact("mode") and proj.fact("mode").payload else None),
        "modules": [program.entities[n].name for n in program.order
                    if program.entities[n].kind == "module"],
    }
    sys.stdout.write(_json_envelope("sem.context.v1", **ctx) + "\n")
    return 0


def cmd_symbols(args) -> int:
    """Full source graph (sem.symbols.v1): every entity with kind + row count."""
    program = parse_compact(_read_program_source(args.path))
    symbols = [
        {"name": program.entities[n].name, "kind": program.entities[n].kind,
         "rows": len(program.entities[n].rows), "line": program.entities[n].line}
        for n in program.order
    ]
    sys.stdout.write(_json_envelope("sem.symbols.v1", symbols=symbols) + "\n")
    return 0


def _doc_entries(program: Program) -> list:
    out = []
    for n in program.order:
        e = program.entities[n]
        purpose = e.fact("purpose")
        ptext = (purpose.payload[-1].strip('"') if purpose and purpose.payload else "")
        out.append({"name": e.name, "kind": e.kind, "purpose": ptext})
    return out


def _docs_index_init(db_path: str):
    import os
    import sqlite3
    parent = os.path.dirname(os.path.abspath(db_path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    conn = sqlite3.connect(db_path)
    conn.execute(
        "CREATE TABLE IF NOT EXISTS docs_meta ("
        "path TEXT PRIMARY KEY, digest TEXT NOT NULL, mtime_ns INTEGER NOT NULL, "
        "entry_count INTEGER NOT NULL, indexed_at TEXT NOT NULL)"
    )
    conn.execute(
        "CREATE TABLE IF NOT EXISTS docs_entries ("
        "path TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, "
        "purpose TEXT NOT NULL, text TEXT NOT NULL, "
        "PRIMARY KEY(path, name))"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS docs_entries_text_idx "
        "ON docs_entries(name, purpose)"
    )
    return conn


def _docs_source_paths(path: str) -> list[str]:
    import os
    if path != "-" and os.path.isdir(path):
        return _project_source_paths(path)
    return [path]


def _docs_source_stamp(path: str, source: str) -> tuple[str, int]:
    import hashlib
    import os
    digest = hashlib.sha256(source.encode("utf-8")).hexdigest()
    mtimes = []
    for src_path in _docs_source_paths(path):
        if src_path != "-" and os.path.exists(src_path):
            mtimes.append(os.stat(src_path).st_mtime_ns)
    return digest, max(mtimes) if mtimes else 0


def _docs_index_write(path: str, db_path: str) -> dict:
    import datetime
    import os
    source = _read_program_source(path)
    program = parse_compact(source)
    entries = _doc_entries(program)
    digest, mtime_ns = _docs_source_stamp(path, source)
    scope = os.path.abspath(path) if path != "-" else "-"
    conn = _docs_index_init(db_path)
    try:
        old = conn.execute(
            "SELECT digest, entry_count FROM docs_meta WHERE path = ?",
            (scope,),
        ).fetchone()
        status = "fresh" if old and old[0] == digest else (
            "created" if old is None else "refreshed")
        if status != "fresh":
            conn.execute("DELETE FROM docs_entries WHERE path = ?", (scope,))
            conn.executemany(
                "INSERT INTO docs_entries(path, name, kind, purpose, text) "
                "VALUES (?, ?, ?, ?, ?)",
                [(scope, e["name"], e["kind"], e["purpose"],
                  f'{e["name"]} {e["kind"]} {e["purpose"]}') for e in entries],
            )
            conn.execute(
                "INSERT INTO docs_meta(path, digest, mtime_ns, entry_count, indexed_at) "
                "VALUES (?, ?, ?, ?, ?) "
                "ON CONFLICT(path) DO UPDATE SET "
                "digest=excluded.digest, mtime_ns=excluded.mtime_ns, "
                "entry_count=excluded.entry_count, indexed_at=excluded.indexed_at",
                (scope, digest, mtime_ns, len(entries),
                 datetime.datetime.now(datetime.UTC).isoformat(timespec="seconds").replace("+00:00", "Z")),
            )
            conn.commit()
        return {
            "ok": True,
            "status": status,
            "path": scope,
            "db": os.path.abspath(db_path),
            "count": len(entries),
            "previousCount": old[1] if old else None,
        }
    finally:
        conn.close()


def _docs_index_search(db_path: str, query: str, scope: Optional[str] = None,
                       limit: int = 10) -> dict:
    import os
    conn = _docs_index_init(db_path)
    try:
        params: list = []
        where = ""
        if scope:
            where = "WHERE path = ?"
            params.append(os.path.abspath(scope))
        rows = conn.execute(
            "SELECT path, name, kind, purpose, text FROM docs_entries " + where,
            params,
        ).fetchall()
    finally:
        conn.close()
    terms = [t for t in query.lower().split() if t]
    scored = []
    for path, name, kind, purpose, text in rows:
        hay = text.lower()
        score = sum(hay.count(t) for t in terms)
        if score:
            scored.append({
                "path": path,
                "name": name,
                "kind": kind,
                "purpose": purpose,
                "score": score,
            })
    scored.sort(key=lambda x: (-x["score"], x["path"], x["name"]))
    return {
        "ok": True,
        "db": os.path.abspath(db_path),
        "query": query,
        "scope": os.path.abspath(scope) if scope else None,
        "results": scored[:limit],
        "count": len(scored[:limit]),
    }


def cmd_docs(args) -> int:
    """Docs catalog over program entities (no third-party dep): list / get / a
    keyword-ranked `--search` (sem.docsIndex.v1 / sem.docs.v1 / sem.docsSearch.v1)."""
    if args.path == "index" and getattr(args, "db", None):
        if not getattr(args, "extra", None):
            sys.stdout.write(_json_envelope(
                "sem.docsIndex.v1", ok=False, status="missing-path",
                db=args.db, hint="usage: docs index <path> --db <file>") + "\n")
            return 2
        payload = _docs_index_write(args.extra[0], args.db)
        sys.stdout.write(_json_envelope("sem.docsIndex.v1", **payload) + "\n")
        return 0
    if args.path == "search" and getattr(args, "db", None):
        query = " ".join(getattr(args, "extra", [])).strip()
        if not query:
            sys.stdout.write(_json_envelope(
                "sem.docsSearch.v1", ok=False, status="missing-query",
                db=args.db, hint="usage: docs search <query> --db <file>") + "\n")
            return 2
        payload = _docs_index_search(
            args.db, query, scope=getattr(args, "scope", None),
            limit=getattr(args, "limit", None) or 10)
        sys.stdout.write(_json_envelope("sem.docsSearch.v1", **payload) + "\n")
        return 0
    if not args.path:
        # R1: no path -> browse the builtin/stdlib CATALOG (list/get/search), the
        # surface `docs --help` advertises, instead of erroring missing-path. The
        # catalog was otherwise reachable only through `docs search --db`.
        entries = _catalog_doc_entries()
        _docs_source = "catalog"
    else:
        entries = _doc_entries(parse_compact(_read_program_source(args.path)))
        _docs_source = args.path
    if getattr(args, "search", None):
        terms = [t for t in args.search.lower().split() if t]
        scored = []
        for e in entries:
            hay = (e["name"] + " " + e["purpose"]).lower()
            score = sum(hay.count(t) for t in terms)
            if score:
                scored.append({**e, "score": score})
        scored.sort(key=lambda x: (-x["score"], x["name"]))
        sys.stdout.write(_json_envelope(
            "sem.docsSearch.v1", query=args.search, source=_docs_source,
            results=scored[:10]) + "\n")
    elif getattr(args, "get", None):
        match = next((e for e in entries if e["name"] == args.get), None)
        fuzzy = False
        if match is None:  # builtin/std target lookup from shipped .semsig files
            family_sigs = _builtin_family_signatures(args.get)
            if family_sigs:
                match = _signature_family_doc_entry(args.get, family_sigs)
            else:
                sig = _builtin_target_signature(args.get)
                if sig is not None:
                    match = _signature_doc_entry(sig)
        if match is None:  # near-miss name -> closest entity (agentic-friendly)
            import difflib
            close = difflib.get_close_matches(
                args.get, [e["name"] for e in entries], n=1, cutoff=0.5)
            if close:
                match = next(e for e in entries if e["name"] == close[0])
                fuzzy = True
        sys.stdout.write(_json_envelope(
            "sem.docs.v1", ok=(match is not None), fuzzyMatch=fuzzy,
            source=_docs_source, entity=match) + "\n")
    else:
        sys.stdout.write(_json_envelope(
            "sem.docsIndex.v1", count=len(entries), source=_docs_source,
            entries=[{"name": e["name"], "kind": e["kind"]} for e in entries]) + "\n")
    return 0


def cmd_dev(args) -> int:
    """Dev contract (sem.dev.v1): one check+runnability cycle reporting whether
    the surface is close to runnable (a single tick of the watch/restart loop)."""
    program = parse_compact(_read_program_source(args.path))
    diags = lint(program)
    errors = [d for d in diags if d.severity == "error"]
    projects = program.of_kind("project")
    target = (projects[0].fact("target").payload[0]
              if projects and projects[0].fact("target") and projects[0].fact("target").payload
              else None)
    runnable = not errors and target == "console"
    nxt = ([_next_command_for_source(["run", args.path], "JIT-run", args.path),
            _next_command_for_source(["build", args.path], "compile to a native exe", args.path)]
           if runnable else
           [_next_command_for_source(["check", args.path], "resolve source diagnostics first", args.path)])
    sys.stdout.write(_json_envelope(
        "sem.dev.v1", checkStatus=("lint-diagnostics" if errors else "ok"),
        runnable=runnable, target=target, nextCommands=nxt) + "\n")
    return 0


def cmd_size(args) -> int:
    """Cheap footprint probe (sem.size.v1): entity + row counts by kind."""
    program = parse_compact(_read_program_source(args.path))
    by_kind: dict = {}
    rows = 0
    for n in program.order:
        ent = program.entities[n]
        by_kind[ent.kind] = by_kind.get(ent.kind, 0) + 1
        rows += 1 + len(ent.rows)
    sys.stdout.write(_json_envelope(
        "sem.size.v1", entities=len(program.order), rows=rows, byKind=by_kind) + "\n")
    return 0


def _check_lane_fields(errors: list, warnings: list, strict: bool) -> dict:
    warning_count = len(warnings)
    if strict:
        warning_policy = (
            "strict mode promotes T3 opinionated warnings to errors; any remaining "
            "warnings are advisory"
        )
    else:
        warning_policy = (
            "warnings are reported but do not fail check; use --strict for the "
            "stricter source gate and require zero warnings in CI if desired"
        )
    if warning_count and not strict:
        note = (
            f"check is static-only; {warning_count} warning(s) reported but not "
            "enforced. Run with --strict to block T3 warnings, then run/test/build "
            "to prove behavior."
        )
    elif warning_count:
        note = (
            f"check is static-only; {warning_count} advisory warning(s) remain. "
            "Run/test/build to prove behavior."
        )
    else:
        note = (
            "check is static-only parse+lint; it is not an execution, test, build, "
            "or runtime authorization proof."
        )
    return {
        "lane": "static-source",
        "strict": bool(strict),
        "errorCount": len(errors),
        "warningCount": warning_count,
        "warningPolicy": warning_policy,
        "runtimeProof": "not-run",
        "note": note,
    }


def _check_program_status(path: str, strict: bool = False) -> dict:
    """R-003: classify one checkable surface (a single file or a composed project
    directory) into the source-lane status used by `check`. Shared by the
    single-program path and the per-child workspace summaries so the two cannot
    drift. A parse failure is `compiler-error`; otherwise the lint severity picks
    `lint-diagnostics` / `ok-with-warnings` / `ok`."""
    try:
        _source, program = _load_program_for_path(path)
    except EavError as exc:
        return {
            "status": "compiler-error", "ok": False, "diagnostics": [str(exc)],
            **_check_lane_fields([exc], [], strict),
        }
    diags = lint(program)
    diags = _filter_diagnostics_strict(diags, strict)
    errors = [d for d in diags if d.severity == "error"]
    warnings = [d for d in diags if d.severity == "warning"]
    status = ("lint-diagnostics" if errors
              else "ok-with-warnings" if warnings else "ok")
    return {"status": status, "ok": status in ("ok", "ok-with-warnings"),
            "diagnostics": [d.render() for d in diags],
            **_check_lane_fields(errors, warnings, strict)}


def check_workspace(root: str, strict: bool = False) -> dict:
    """R-003: check a *workspace* directory (not itself a project root) by checking
    each child independently and never composing unrelated fixtures into one
    program. Each app/example/std/signature/manifest child gets its own source
    lane status; `invalid_corpus/` and build/cache/asset dirs are excluded. The
    top-level status is `workspace`; `ok` is true only when every child is clean.
    This replaces the old behavior where the bare experiment root was glued into
    one program and reported a misleading `compiler-error` from a negative
    fixture's `=` token."""
    children = discover_workspace(root)
    summaries = []
    all_ok = True
    error_count = 0
    warning_count = 0
    for child in children:
        result = _check_program_status(child["path"], strict)
        all_ok = all_ok and result["ok"]
        error_count += int(result.get("errorCount", 0))
        warning_count += int(result.get("warningCount", 0))
        summaries.append({"name": child["name"].replace("\\", "/"),
                          "kind": child["kind"], "status": result["status"],
                          "ok": result["ok"],
                          "diagnostics": result["diagnostics"],
                          "errorCount": result.get("errorCount", 0),
                          "warningCount": result.get("warningCount", 0)})
    fields = _check_lane_fields([None] * error_count, [None] * warning_count, strict)
    return {"status": "workspace", "ok": all_ok,
            "diagnostics": [], "typedComments": [], "nextCommands": [],
            "childCount": len(summaries), "children": summaries, **fields}


def _check_proof_next_commands(path: str, program: Program, has_tests: bool) -> list:
    projects = program.of_kind("project")
    targets = [row.payload[0] for proj in projects for row in proj.facts("target")
               if row.payload] or ["console"]
    commands: list[dict] = []
    if "wasm" in targets and not any(t in targets for t in ("console", "webServer")):
        commands.append(_next_command_for_source(
            ["wasm", path], "compile to WebAssembly; check is static-only", path))
        if has_tests:
            commands.append(_next_command_for_source(
                ["test", path], "run the test operations", path))
        return commands
    commands.append(_next_command_for_source(
        ["run", path], "execute the program; check is static-only", path))
    if has_tests:
        commands.append(_next_command_for_source(
            ["test", path], "run the test operations", path))
    commands.append(_next_command_for_source(
        ["build", path], "compile to a native exe", path))
    if "wasm" in targets:
        commands.append(_next_command_for_source(
            ["wasm", path], "compile the wasm target", path))
    return commands


def cmd_check(args) -> int:
    """Source lane (sem.check.v1): parse + lint, classify ok / ok-with-warnings /
    lint-diagnostics / compiler-error (README check/readiness split).

    R-003: a directory that is not itself a project root is treated as a workspace
    — each child app/example/std/signature is checked independently and reported
    with per-child summaries, instead of composing every unrelated fixture into one
    program and surfacing a misleading compiler error from a negative fixture."""
    import os
    strict = getattr(args, "strict", False)
    if (args.path != "-" and os.path.isdir(args.path)
            and not is_project_root(args.path)):
        report = check_workspace(args.path, strict)
        sys.stdout.write(_json_envelope("sem.check.v1", **report) + "\n")
        return 0 if report["ok"] else 1
    try:
        _source, program = _load_program_for_path(args.path)
    except EavError as exc:
        sys.stdout.write(_json_envelope(
            "sem.check.v1", status="compiler-error", ok=False,
            diagnostics=[str(exc)],
            **_check_lane_fields([exc], [], strict)) + "\n")
        return 1  # R-093: a compiler error is a nonzero exit, matching the workspace lane
    diags = lint(program)
    diags = _filter_diagnostics_strict(diags, strict)
    errors = [d for d in diags if d.severity == "error"]
    warnings = [d for d in diags if d.severity == "warning"]
    status = ("lint-diagnostics" if errors
              else "ok-with-warnings" if warnings else "ok")
    # README §24/§32.3 #20: machine-facing next steps. Only recommend `test` when
    # the program actually has `tag test` operations — under the R-158/R-173
    # no-tests gate a `test` run that discovers nothing exits 1 (no vacuous pass),
    # so recommending it for a test-free file would advertise a `replayable` next
    # step that is guaranteed to fail (the agent-loop contract, WS4-122). Mirror
    # cmd_test's own discovery: a project root composes its companion *.test.sem
    # sources (load_test_project), which the plain check parse above excludes, so a
    # scaffold's co-located tests are still seen here.
    try:
        if (args.path != "-" and os.path.isdir(args.path)
                and is_project_root(args.path)):
            has_tests = bool(discover_tests(load_test_project(args.path)))
        else:
            has_tests = bool(discover_tests(program))
    except EavError:
        has_tests = True  # discovery failed; keep the prior `test` suggestion
    if status == "lint-diagnostics":
        nxt = [_next_command_for_source(["fix", args.path, "--plan"],
                                        "derive a repair plan for the errors", args.path)]
    elif status == "ok-with-warnings":
        nxt = [_next_command_for_source(["fix", args.path, "--plan", "--include-warnings"],
                                        "review warning cleanup", args.path)]
        nxt.extend(_check_proof_next_commands(args.path, program, has_tests))
    else:
        nxt = _check_proof_next_commands(args.path, program, has_tests)
    # R-080: surface retained typed comments (`# security:`/`# failure:` …) on
    # the machine-facing check envelope so important notes stay reviewable in
    # downstream tooling instead of disappearing.
    typed = [{"tag": t, "text": txt, "line": ln}
             for (t, txt, ln) in program.typed_comments]
    sys.stdout.write(_json_envelope(
        "sem.check.v1", status=status, ok=(status in ("ok", "ok-with-warnings")),
        diagnostics=_structured_diags(diags), typedComments=typed,
        nextCommands=nxt, **_check_lane_fields(errors, warnings, strict)) + "\n")
    # R-093: error-severity diagnostics (incl. --strict-promoted warnings) exit
    # nonzero; clean and warning-only single files stay 0, matching the workspace lane.
    return 1 if status == "lint-diagnostics" else 0


def _verify_once_payload(path: str, strict: bool = False) -> tuple[dict, int]:
    """Build one sem.verify.v1 payload and return (payload, process_exit_code)."""
    import os
    lanes = {
        "check": {"ok": False, "status": "not-run"},
        "test": {"ok": True, "status": "not-run"},
        "run": {"ok": False, "status": "not-run"},
    }
    try:
        source, program = _load_program_for_path(path)
    except EavError as exc:
        lanes["check"] = {
            "ok": False,
            "status": "compiler-error",
            "diagnostics": [{"code": exc.code, "severity": "error",
                             "line": exc.line, "entity": None,
                             "message": exc.message,
                             "rendered": f"semanticscript: {exc}"}],
        }
        return {"status": "blocked", "path": path, "strict": strict, "lanes": lanes}, 1

    diags = _filter_diagnostics_strict(lint(program), strict)
    errors = [d for d in diags if d.severity == "error"]
    warnings = [d for d in diags if d.severity == "warning"]
    check_status = ("lint-diagnostics" if errors
                    else "ok-with-warnings" if warnings else "ok")
    lanes["check"] = {
        "ok": not errors,
        "status": check_status,
        "diagnostics": _structured_diags(diags),
        **_check_lane_fields(errors, warnings, strict),
    }
    if errors:
        lanes["test"] = {"ok": True, "status": "skipped", "reason": "check failed"}
        lanes["run"] = {"ok": True, "status": "skipped", "reason": "check failed"}
        return {"status": "blocked", "path": path, "strict": strict, "lanes": lanes}, 1

    try:
        if path != "-" and os.path.isdir(path) and is_project_root(path):
            test_program = load_test_project(path)
            test_program.source_root = _program_source_root_for_path(path)
        else:
            test_program = program
        test_diags = _filter_diagnostics_strict(lint(test_program), strict)
        test_errors = [d for d in test_diags if d.severity == "error"]
        tests_by_lane = discover_tests(test_program)
        test_count = sum(len(v) for v in tests_by_lane.values())
        if test_errors:
            lanes["test"] = {
                "ok": False,
                "status": "blocked",
                "diagnostics": _structured_diags(test_errors),
            }
        elif test_count == 0:
            lanes["test"] = {"ok": True, "status": "skipped", "reason": "no tag test operations"}
        else:
            report = run_tests(test_program)
            test_ok = report.get("compositeStatus") == "pass"
            lanes["test"] = {"ok": test_ok, "status": report.get("compositeStatus"), **report}
    except EavError as exc:
        lanes["test"] = {
            "ok": False,
            "status": "compiler-error",
            "diagnostics": [{"code": exc.code, "severity": "error",
                             "line": exc.line, "entity": None,
                             "message": exc.message,
                             "rendered": f"semanticscript: {exc}"}],
        }

    # W2-H: only the console target is a terminating run-to-exit program. A
    # `webServer` (or wasm) entry blocks in its server loop and never exits, so
    # driving it through the run lane just wedges `verify` until the eval timeout
    # fires (and risks a zombie server holding the port on Windows). Skip the run
    # lane for a non-console target — its behavior is proven by a live harness /
    # integration test, not by running it to completion. (Mirrors `bench`, which
    # reports a non-console target as not runnable.)
    run_target = _program_target(program)
    if run_target != "console":
        lanes["run"] = {
            "ok": True,
            "status": "skipped",
            "reason": (f"target {run_target!r} is a long-running entry that does "
                       f"not run to exit; the run lane cannot prove it — verify it "
                       f"with a live/integration harness"),
            "target": run_target,
        }
    else:
        out, err, code = _record_run_full(
            source, cwd=getattr(program, "source_root", None))
        run_status, panic = _classify_run(out, err, code)
        lanes["run"] = {
            "ok": code == 0,
            "status": run_status,
            "exitCode": code,
            "stdout": out,
            "stderr": err,
            "stdoutLines": _stdout_lines(out),
        }
        if panic is not None:
            lanes["run"]["panic"] = panic

    ok = bool(lanes["check"].get("ok") and lanes["test"].get("ok") and lanes["run"].get("ok"))
    status = "ok" if ok else ("blocked" if lanes["test"].get("status") in ("blocked", "compiler-error") else "failed")
    return {"status": status, "path": path, "strict": strict, "lanes": lanes}, (0 if ok else 1)


def _emit_verify_payload(payload: dict, want_json: bool) -> None:
    ok = payload.get("status") == "ok"
    if want_json:
        sys.stdout.write(_json_envelope("sem.verify.v1", ok=ok, **payload) + "\n")
    else:
        lanes = payload["lanes"]
        if lanes["check"].get("status") == "compiler-error":
            diag = (lanes["check"].get("diagnostics") or [{}])[0]
            sys.stderr.write(f"verify: check blocked: {diag.get('rendered') or diag.get('message')}\n")
            return
        sys.stdout.write(f"check: {lanes['check']['status']}\n")
        sys.stdout.write(f"test: {lanes['test']['status']}\n")
        exit_code = lanes["run"].get("exitCode")
        suffix = f" ({exit_code})" if exit_code is not None else ""
        sys.stdout.write(f"run: {lanes['run']['status']}{suffix}\n")


def _verify_watch_files(path: str) -> list[str]:
    """Files whose content should trigger a verify --watch rerun."""
    import os
    if path == "-":
        raise EavError("verify --watch does not support stdin; watch a file or project directory")
    if os.path.isdir(path) and is_project_root(path):
        files = list(_project_source_paths(path))
        try:
            tests = discover_project_tests(path)
            for rel in tests.get("coLocated", []) + tests.get("testsDir", []):
                files.append(os.path.join(path, rel))
        except Exception:
            pass
    else:
        files = [path]
    out: list[str] = []
    seen: set = set()
    for filename in files:
        full = os.path.abspath(filename)
        if full not in seen:
            seen.add(full)
            out.append(full)
    return sorted(out)


def _verify_watch_digest(path: str) -> tuple[str, list[str]]:
    import hashlib
    import os
    files = _verify_watch_files(path)
    digest = hashlib.sha256()
    for filename in files:
        digest.update(filename.encode("utf-8", "surrogateescape"))
        digest.update(b"\0")
        try:
            st = os.stat(filename)
            digest.update(str(st.st_size).encode("ascii"))
            digest.update(b":")
            with open(filename, "rb") as fh:
                for chunk in iter(lambda: fh.read(1 << 16), b""):
                    digest.update(chunk)
        except OSError:
            digest.update(b"<missing>")
        digest.update(b"\0")
    return digest.hexdigest(), files


def _cmd_verify_watch(args) -> int:
    import time
    strict = getattr(args, "strict", False)
    want_json = getattr(args, "json", False)
    interval = max(0.05, float(getattr(args, "watch_interval", 1.0) or 1.0))
    limit = getattr(args, "watch_count", None)
    if limit is not None and limit <= 0:
        raise EavError("--watch-count must be positive")
    last_digest = None
    emitted = 0
    last_rc = 0
    try:
        while True:
            digest, files = _verify_watch_digest(args.path)
            if digest != last_digest:
                payload, rc = _verify_once_payload(args.path, strict)
                emitted += 1
                payload["watch"] = {
                    "mode": "watch",
                    "sequence": emitted,
                    "digest": digest,
                    "fileCount": len(files),
                    "intervalSeconds": interval,
                }
                _emit_verify_payload(payload, want_json)
                try:
                    sys.stdout.flush()
                    sys.stderr.flush()
                except Exception:
                    pass
                last_digest = digest
                last_rc = rc
                if limit is not None and emitted >= limit:
                    return last_rc
            time.sleep(interval)
    except KeyboardInterrupt:
        if not want_json:
            sys.stderr.write("verify: watch stopped\n")
        return last_rc


def cmd_verify(args) -> int:
    """G3/G4: one-shot or watched check + test + run gate (sem.verify.v1)."""
    if getattr(args, "watch", False):
        return _cmd_verify_watch(args)
    payload, rc = _verify_once_payload(args.path, getattr(args, "strict", False))
    _emit_verify_payload(payload, getattr(args, "json", False))
    return rc


def cmd_readiness(args) -> int:
    """Environment lane (sem.readiness.v1): toolchain availability. Exits nonzero
    unless ok (README readiness lane)."""
    cc = _find_c_compiler()
    try:
        import llvmlite  # noqa: F401
        have_llvm = True
    except ImportError:
        have_llvm = False
    ok = bool(cc) and have_llvm
    status = "ok" if ok else "degraded"
    sys.stdout.write(_json_envelope(
        "sem.readiness.v1", status=status, ok=ok,
        cCompiler=bool(cc), llvmlite=have_llvm) + "\n")
    return 0 if ok else 1


def cmd_stdlib_readiness(args) -> int:
    """WS3-110: emit the generated stdlib readiness ledger (sem.stdlibReadiness.v1),
    classifying every `standard.*` module by maturity (native/lowered/intrinsic/
    signature-only). Exits nonzero if any PUBLIC module is signature-only without an
    explicit deferred status — an unbacked public API that would `check` clean and
    then fail at lower/run, so app authors can tell cohesive platform APIs from
    scaffolding."""
    ledger = stdlib_readiness_ledger()
    # the GATE is always computed over the FULL platform — WS3-120: a tier filter
    # narrows the VIEW but never the gate, so a failure cannot be hidden by asking
    # only for one tier, and a secondary module faces the same gate as a core one.
    unbacked = sorted(m for m, e in ledger.items() if e["unbackedPublic"])
    leaks = sorted(m for m, e in ledger.items() if e["unacknowledgedScratchPointer"])
    doc_gaps = sorted(m for m, e in ledger.items() if e["documentationGap"])
    # the gate fails on an unbacked public API, an un-graduated raw scratch-pointer
    # leak, OR an undocumented public API (missing description / unowned-cleanup) —
    # the three clauses of WS3-110's `->test`.
    ok = not unbacked and not leaks and not doc_gaps
    parts = [p for p, hit in (("unbacked-public", unbacked),
                              ("scratch-pointer-leak", leaks),
                              ("documentation-gap", doc_gaps)) if hit]
    status = "+".join(parts) if parts else "ok"
    counts = {s: sum(1 for e in ledger.values() if e["status"] == s)
              for s in ("native", "lowered", "intrinsic", "signature-only")}
    tier_counts = {t: sum(1 for e in ledger.values() if e["tier"] == t)
                   for t in ("core", "secondary")}
    # tracked (acknowledged) scratch-pointer contracts, for graduation visibility
    tracked_scratch = {m: e["scratchPointerApis"] for m, e in ledger.items()
                       if e["scratchPointerApis"]}
    # WS3-120: `--tier core|secondary` filters the displayed inventory only.
    tier_filter = getattr(args, "tier", None)
    view = {m: e for m, e in ledger.items()
            if not tier_filter or e["tier"] == tier_filter}
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope(
            "sem.stdlibReadiness.v1", ok=ok,
            status=status,
            counts=counts, tierCounts=tier_counts, tierFilter=tier_filter,
            unbackedPublic=unbacked,
            scratchPointerLeak=leaks, scratchPointerApis=tracked_scratch,
            documentationGap=doc_gaps,
            deferred=sorted(m for m, e in ledger.items() if e["deferred"]),
            modules=view,
            ws3PlatformProfile=ws3_platform_profile()) + "\n")
    else:
        for mod, e in sorted(view.items()):
            mark = " (deferred)" if e["deferred"] else ""
            flag = "  <- UNBACKED PUBLIC" if e["unbackedPublic"] else ""
            if e["unacknowledgedScratchPointer"]:
                flag += "  <- RAW SCRATCH-POINTER LEAK"
            elif e["scratchPointerApis"]:
                flag += f"  (scratch-pointer: {', '.join(e['scratchPointerApis'])})"
            if e["documentationGap"]:
                gaps = e["undocumentedApis"] + [
                    f"{n}(owns-no-cleanup)" for n in e["ownsWithoutCleanup"]]
                flag += f"  <- DOC GAP: {', '.join(gaps)}"
            tier = "" if e["tier"] == "core" else "  [secondary]"
            print(f"{mod:14} {e['status']:15}{tier}{mark}{flag}")
        if unbacked:
            sys.stderr.write(
                f"semanticscript: unbacked public stdlib modules (no implementation, "
                f"not deferred): {', '.join(unbacked)}\n")
        if leaks:
            sys.stderr.write(
                f"semanticscript: public stdlib modules exposing an un-graduated raw "
                f"scratch-pointer contract (add to STDLIB_SCRATCH_POINTER_ACKNOWLEDGED "
                f"only with a graduation plan, or wrap in an owned type): "
                f"{', '.join(leaks)}\n")
        if doc_gaps:
            sys.stderr.write(
                f"semanticscript: public stdlib modules with undocumented intrinsics "
                f"(every public intrinsic needs a `purpose` row, and any `owns` row "
                f"needs a `cleanedBy` target): {', '.join(doc_gaps)}\n")
    return 0 if ok else 1


def _default_build_output(path: str, explicit_output: Optional[str],
                          ir_sha256: Optional[str] = None) -> str:
    """Resolve the build output path (README §28.2/§28.4).

    R-014 keeps project-directory builds under gitignored `dist/`. WS3-150 adds a
    content-addressed default name (`app-<irhash>` / `<file>-<irhash>`) so a
    changed program publishes a new artifact path instead of colliding with a
    running exe. Explicit `--output` / platform output rows still win unchanged.
    """
    import os
    suffix = ".exe" if sys.platform == "win32" else ""
    if explicit_output:
        explicit_output = os.path.normpath(explicit_output)
        root, ext = os.path.splitext(explicit_output)
        return explicit_output if not suffix or ext else root + suffix
    hash_part = ""
    if ir_sha256:
        cleaned = "".join(c for c in ir_sha256.lower() if c in "0123456789abcdef")
        if cleaned:
            hash_part = "-" + cleaned[:16]
    if path == "-":
        return "a" + hash_part + suffix
    if os.path.isdir(path):
        return os.path.join(path, "dist", "app" + hash_part + suffix)
    return os.path.splitext(path)[0] + hash_part + suffix


def _devx_payload(mode: str, path: str, program: Program, source: str, args) -> dict:
    focus = getattr(args, "focus", None)
    intent = getattr(args, "intent", None)
    if mode == "author":
        return {"mode": mode, **_devx_author_surface(program, focus, intent)}
    if mode == "intent":
        return {"mode": mode, "status": "ok",
                "candidates": _devx_intent_candidates(intent)}
    if mode == "contracts":
        return {"mode": mode, **_devx_contract_surface(program)}
    if mode == "mock":
        return {"mode": mode, **_devx_mock_surface(
            program, source=source,
            record_replay=bool(getattr(args, "record_replay", False)))}
    if mode == "authority":
        return {"mode": mode, **_devx_authority_surface(program)}
    if mode == "repl":
        return {"mode": mode, **_devx_repl_surface(program, intent)}
    if mode == "improve":
        return {"mode": mode, **_devx_improve_surface(program, path)}
    if mode == "adversarial":
        return {"mode": mode, **_devx_adversarial_surface(program)}
    if mode == "perf":
        return {"mode": mode, **_devx_perf_surface(program, path)}
    if mode == "all":
        return {
            "mode": mode,
            "status": "ok",
            "author": _devx_author_surface(program, focus, intent),
            "intent": {"candidates": _devx_intent_candidates(intent)},
            "contracts": _devx_contract_surface(program),
            "mock": _devx_mock_surface(program, source=source, record_replay=False),
            "authority": _devx_authority_surface(program),
            "repl": _devx_repl_surface(program, intent),
            "improve": _devx_improve_surface(program, path),
            "adversarial": _devx_adversarial_surface(program),
            "perf": _devx_perf_surface(program, path),
        }
    raise EavError(f"unknown devx mode {mode!r}")


def cmd_devx(args) -> int:
    """DEVX-NEXT agent capability surface (sem.devx.v1)."""
    mode = getattr(args, "mode", "all")
    if mode == "diff":
        if not getattr(args, "compare", None):
            raise EavError("devx --mode diff requires --compare <new-path>")
        old = parse_compact(_read_program_source(args.path))
        new = parse_compact(_read_program_source(args.compare))
        payload = {
            "mode": mode,
            "status": "ok",
            "changes": semantic_diff_structured(old, new),
            "human": semantic_diff(old, new),
        }
    else:
        source = _read_program_source(args.path)
        program = parse_compact(source)
        payload = _devx_payload(mode, args.path, program, source, args)
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope("sem.devx.v1", **payload) + "\n")
    else:
        sys.stdout.write(f"devx {payload.get('mode')}: {payload.get('status', 'ok')}\n")
        if payload.get("mode") == "diff":
            for line in payload.get("human", []):
                sys.stdout.write(line + "\n")
        else:
            sys.stdout.write(
                "rerun with --json for the structured authoring/contract payload\n")
    return 0


def cmd_compensate(args) -> int:
    """COMPENSATE agent mitigation surface (sem.compensate.v1)."""
    source = _read_program_source(args.path)
    payload = _compensate_payload(
        getattr(args, "mode", "all"), args.path, source, args)
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope("sem.compensate.v1", **payload) + "\n")
    else:
        sys.stdout.write(
            f"compensate {payload.get('mode')}: {payload.get('status', 'ok')}\n")
        sys.stdout.write(
            "rerun with --json for codegen, maturity, cost, memory, env, "
            "checkpoint, and alternatives detail\n")
    return 0


def cmd_package_manifest(args) -> int:
    """Validate and emit app packaging metadata from build.sem (R-046)."""
    want_json = getattr(args, "json", False)
    try:
        manifest = package_manifest_for_path(
            args.path,
            profile=getattr(args, "profile", None),
            platform=getattr(args, "platform", None),
        )
    except (EavError, OSError) as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.packageManifest.v1",
                ok=False,
                status="invalid-manifest",
                message=str(exc),
            ) + "\n")
        else:
            sys.stderr.write(f"semanticscript: {exc}\n")
        return 2

    if want_json:
        sys.stdout.write(_json_envelope(
            "sem.packageManifest.v1",
            ok=True,
            status="ok",
            manifest=manifest,
        ) + "\n")
    else:
        sys.stdout.write(f"project: {manifest['project']}\n")
        sys.stdout.write(f"productName: {manifest['productName']}\n")
        sys.stdout.write(f"packageId: {manifest['packageId']}\n")
        if manifest.get("packageVersion"):
            sys.stdout.write(f"packageVersion: {manifest['packageVersion']}\n")
        if manifest.get("profile"):
            sys.stdout.write(f"profile: {manifest['profile']}\n")
        if manifest.get("platform"):
            sys.stdout.write(f"platform: {manifest['platform']}\n")
        if manifest.get("output"):
            sys.stdout.write(f"output: {manifest['output']}\n")
        for icon in manifest["icons"]:
            sys.stdout.write(f"icon {icon['name']}: {icon['path']}\n")
        for resource in manifest["resources"]:
            sys.stdout.write(f"resource {resource['name']}: {resource['path']}\n")
    return 0


def cmd_runtime_config(args) -> int:
    """Validate and emit runtime/deployment config from build.sem (R-060)."""
    want_json = getattr(args, "json", False)
    try:
        config = runtime_config_for_path(
            args.path,
            profile=getattr(args, "profile", None),
        )
    except (EavError, OSError) as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.runtimeConfig.v1",
                ok=False,
                status="invalid-config",
                message=str(exc),
            ) + "\n")
        else:
            sys.stderr.write(f"semanticscript: {exc}\n")
        return 2

    status = "ok" if config["ready"] else "blocked"
    if want_json:
        sys.stdout.write(_json_envelope(
            "sem.runtimeConfig.v1",
            ok=config["ready"],
            status=status,
            config=config,
        ) + "\n")
    else:
        sys.stdout.write(f"project: {config['project']}\n")
        sys.stdout.write(f"profile: {config['profile']}\n")
        for item in config["values"]:
            sys.stdout.write(
                f"config {item['name']} ({item['type']}): {item['value']}\n")
        for item in config["secrets"]:
            mark = "present" if item["present"] else "missing"
            sys.stdout.write(f"secret {item['name']} ({item['source']}:{item['key']}): {mark}\n")
        for dep in config["deployments"]:
            sys.stdout.write(f"deployment {dep['name']}: {dep['target']}\n")
        for mig in config["migrations"]:
            sys.stdout.write(f"migration {mig['order']}: {mig['operation']}\n")
    return 0 if config["ready"] else 1


def _build_identity(program: Program, platform: Optional[str] = None) -> dict:
    """FIX-2: a content-addressed identity for a built artifact - the sha256 of the
    lowered LLVM IR plus the contract/release version. Surfacing it lets a consumer
    verify reproducibility (same source+toolchain -> same irSha256) and confirm a
    rebuild actually changed, instead of trusting an opaque exe path alone."""
    import hashlib
    ir_sha = None
    try:
        ir_sha = hashlib.sha256(
            str(lower_to_llvm(program, platform)).encode("utf-8")).hexdigest()
    except EavError:
        ir_sha = None
    return {
        "irSha256": ir_sha,
        "contractVersion": CONTRACT_VERSION,
        "releaseVersion": _release_version(),
    }


def cmd_build(args) -> int:
    """Compile a program to a native executable (IR -> clang -> exe). R-017: an
    optional `--platform NAME` selects a declared `platform` entity (triple +
    forPlatform + its `output` row); an unknown platform exits with a structured
    sem.build.v1 error."""
    import os
    want_json = getattr(args, "json", False)

    def _build_failed(status, message, **extra):
        # R-235: every build failure shares the structured sem.build.v1 error
        # shape (the R-017 precedent for unknown-platform) under --json, or a
        # single clean `semanticscript:` line otherwise — never an uncaught
        # OSError traceback (the command was not JSON-native, so main()'s OSError
        # handler re-raised it), and never a divergent fourth shape.
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.build.v1", ok=False, status=status, message=message, **extra) + "\n")
        else:
            sys.stderr.write(f"semanticscript: {message}\n")
        return 2

    # R-251: enforce the supply-chain effect allowlist before building a project
    # (no-op for a single file or a project without a build.sem.lock); an
    # un-allowed dependency effect (SS2805) is a structured build failure.
    try:
        _verify_supply_chain_for_path(args.path)
    except EavError as exc:
        return _build_failed("supply-chain-denied", str(exc))

    _source, program = _load_program_for_path(args.path)
    platform = getattr(args, "platform", None)
    try:
        plat = _resolve_build_platform(program, platform)
    except EavError as exc:
        declared = sorted(n for n in program.order
                          if program.entities[n].kind == "platform")
        # R-017: an unknown platform is a structured sem.build.v1 error even
        # without --json (a deliberate machine-readable build contract).
        sys.stdout.write(_json_envelope(
            "sem.build.v1", ok=False, status="unknown-platform",
            platform=platform, declared=declared, message=str(exc)) + "\n")
        return 2
    # a platform's `output` row is the default output when no --output is given
    out_path = args.output
    if not out_path and plat is not None:
        links = merge_native_links(program, plat.name)
        if links.get("output"):
            base = args.path if os.path.isdir(args.path) else os.path.dirname(
                os.path.abspath(args.path))
            out_path = os.path.join(base, links["output"])
    identity = _build_identity(program, platform)
    ir_hash_for_default = identity.get("irSha256") if not out_path else None
    out_path = _default_build_output(args.path, out_path, ir_hash_for_default)
    try:
        exe = build_executable(program, out_path, platform)
    except EavError as exc:
        return _build_failed("build-error", str(exc), platform=platform, output=out_path)
    except OSError as exc:
        # bad/unwritable output dir, missing toolchain binary, etc. — a structured
        # io-error, not a traceback (R-235).
        return _build_failed("io-error", str(exc), platform=platform, output=out_path)
    if want_json:
        sys.stdout.write(_json_envelope(
            "sem.build.v1", ok=True, status="ok", output=exe,
            identity=identity) + "\n")
    else:
        sys.stdout.write(exe + "\n")
    return 0


def cmd_trace(args) -> int:
    """Print a primary-path trace of an operation."""
    want_json = getattr(args, "json", False)
    multi = getattr(args, "multi_path", False) or getattr(args, "branch_aware", False)
    program = parse_compact(_read_program_source(args.path))
    try:
        if want_json:
            payload = trace_paths(program, args.operation) if multi else {
                "operation": args.operation,
                "branchAware": False,
                "multiPath": False,
                "lines": trace(program, args.operation),
            }
            sys.stdout.write(_json_envelope("sem.trace.v1", status="ok", **payload) + "\n")
            return 0
        if multi:
            payload = trace_paths(program, args.operation)
            for path in payload["paths"]:
                sys.stdout.write(f"{path['name']} {path['status']}\n")
                for event in path["events"]:
                    if event["kind"] == "branch":
                        sys.stdout.write(
                            f"  branch {event['text']} | live: {event['liveBindings']} "
                            f"| defers: {event['deferStack']}\n")
                    elif event["kind"] == "return":
                        sys.stdout.write(
                            f"  return {' '.join(event['payload'])} | defers run "
                            f"(reverse): {event['deferRunOrder']}\n")
                    elif event["kind"] == "path-choice":
                        sys.stdout.write(f"  {event['choice']} -> {event.get('target')}\n")
            return 0
        for line in trace(program, args.operation):
            sys.stdout.write(line + "\n")
        return 0
    except EavError as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.trace.v1", ok=False, status="not-found",
                operation=args.operation,
                diagnostics=[{"message": str(exc), "rendered": f"semanticscript: {exc}"}]) + "\n")
            return 2
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2


def cmd_normalize(args) -> int:
    """Preview normalizing a program (row delta + round-trip gate)."""
    p = normalize_preview(_read_source(args.path))
    sys.stdout.write(
        f"rows {p['rowCount']} -> {p['formattedRowCount']} (delta {p['rowDelta']:+d})\n"
        f"changed: {p['changed']}\n"
        f"round-trip preserved (gate-0): {p['roundTripPreserved']}\n"
    )
    return 0


def cmd_migrate_syntax(args) -> int:
    """Convert compact/current source to canonical EAV with source-map metadata."""
    try:
        src = _read_source(args.path)
        role = classify_sem_file(args.path) if args.path != "-" else "source"
        report = migrate_syntax(
            src,
            from_surface=getattr(args, "from_surface", "auto"),
            to_surface=getattr(args, "to_surface", "canonical"),
            operation=getattr(args, "operation", None),
            role=role,
        )
        if getattr(args, "write", False):
            if args.path == "-":
                raise EavError("migrate-syntax --write needs a file path, not stdin")
            if report["operation"]:
                raise EavError("migrate-syntax --write cannot rewrite an operation slice")
            with open(args.path, "w", encoding="utf-8", newline="") as fh:
                fh.write(report["canonical"])
            report["written"] = True
        else:
            report["written"] = False
    except (EavError, OSError) as exc:
        if getattr(args, "json", False):
            sys.stdout.write(_json_envelope(
                "sem.migrateSyntax.v1", ok=False, status="compiler-error",
                diagnostics=[{"message": str(exc)}]) + "\n")
        else:
            sys.stderr.write(f"semanticscript: {exc}\n")
        return 2

    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope("sem.migrateSyntax.v1", **report) + "\n")
    elif getattr(args, "preview", False):
        sys.stdout.write(
            f"migrate-syntax {report['scope']}: {report['status']}\n"
            f"rows {report['sourceRowsInScope']} -> {report['canonicalRows']} "
            f"(delta {report['rowDelta']:+d})\n"
            f"round-trip preserved: {report['roundTripPreserved']}\n"
        )
    else:
        sys.stdout.write(report["canonical"])
    return 0


def cmd_adoption_gate(args) -> int:
    """R-069: compare current vs converted row count against adoption thresholds."""
    current = _read_program_source(args.current)
    converted = _read_program_source(args.converted)
    report = adoption_gate_report(current, converted, getattr(args, "surface", "canonical"))
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope("sem.adoptionGate.v1", **report) + "\n")
    else:
        pct = report["rowIncreasePercent"]
        pct_text = "n/a" if pct is None else f"{pct:.3f}%"
        sys.stdout.write(
            f"adoption gate {report['authoringSurface']}: {report['status']}\n"
            f"rows {report['currentRows']} -> {report['convertedRows']} ({pct_text})\n"
            f"threshold {report['thresholdPercent']}%\n"
        )
    return 0 if report["ok"] else 1


def cmd_verify_patch(args) -> int:
    """Verify a program is sound; exit 1 if not."""
    report = verify_patch(_read_source(args.path))
    if report["error"]:
        sys.stdout.write(f"FAIL (parse): {report['error']}\n")
        return 1
    for e in report["lintErrors"]:
        sys.stdout.write(f"FAIL (lint): {e}\n")
    sys.stdout.write("OK\n" if report["ok"] else "FAIL\n")
    return 0 if report["ok"] else 1


def cmd_diff(args) -> int:
    """Print the semantic diff between two programs."""
    old = parse_compact(_read_program_source(args.old))
    new = parse_compact(_read_program_source(args.new))
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope(
            "sem.diff.v1", status="ok",
            changes=semantic_diff_structured(old, new),
            human=semantic_diff(old, new)) + "\n")
        return 0
    for line in semantic_diff(old, new):
        sys.stdout.write(line + "\n")
    return 0


def cmd_describe(args) -> int:
    """Summarize an entity's contract. DX-08: if the named entity is not in the
    program but IS a built-in/stdlib target (e.g. `math.divideInt64`), describe its
    declared signature from the .semsig instead of erroring — so `describe` doubles
    as a built-in lookup."""
    program = parse(_read_source(args.path))
    try:
        sys.stdout.write(describe(program, args.entity) + "\n")
        return 0
    except EavError as exc:
        sig = _builtin_target_signature(args.entity)
        if sig is None:
            sys.stderr.write(f"semanticscript: {exc}\n")
            return 2
        lines = [f"intrinsic {sig['target']}"]
        for a in sig["args"]:
            lines.append(f"  arg {a['slot']} {a['type']}")
        if sig["out"]:
            lines.append(f"  out {(sig['outSlot'] + ' ') if sig['outSlot'] else ''}{sig['out']}")
        if sig.get("async") is not None:
            lines.append(f"  async {sig['async']}")
        if sig.get("purpose"):
            lines.append(f"  purpose \"{sig['purpose']}\"")
        if sig.get("risk"):
            lines.append(f"  risk \"{sig['risk']}\"")
        sys.stdout.write("\n".join(lines) + "\n")
        return 0


def cmd_graph(args) -> int:
    """Emit a calls/control graph as DOT or mermaid. R-087: `--json` wraps the
    rendered graph in a versioned sem.graph.v1 envelope (and a parse/render
    error becomes a compiler-error envelope, never an argparse/plaintext error)."""
    want_json = getattr(args, "json", False)
    try:
        program = parse_compact(_read_program_source(args.path))  # R-117/R-165: project dirs + compact
        text = graph(program, args.kind, args.format)
        edges = graph_edges(program, args.kind)
    except EavError as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.graph.v1", status="compiler-error", ok=False,
                diagnostics=[f"semanticscript: {exc}"]) + "\n")
            return 1
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2
    if want_json:
        sys.stdout.write(_json_envelope(
            "sem.graph.v1", status="ok", kind=args.kind,
            format=args.format, graph=text,
            edges=[{"from": a, "to": b} for a, b in edges]) + "\n")
    else:
        sys.stdout.write(text)
    return 0


def cmd_scaffold(args) -> int:
    """Print a canonical scaffold for a pattern."""
    want_json = getattr(args, "json", False)
    try:
        source = scaffold(args.pattern)
        # R-17: emit the *canonical* form (the command's own contract — its docstring
        # says "canonical"). Scaffold templates are authored for readability and drift
        # from fmt's entity/row order, so a freshly-scaffolded, check-green program
        # would otherwise fail `fmt --check` — breaking the scaffold->check->fmt loop.
        source = format_program(parse(source))
        if want_json:
            prog = parse(source)
            diags = lint(prog)
            sys.stdout.write(_json_envelope(
                "sem.scaffold.v1", status="ok", pattern=args.pattern,
                source=source, parseable=True,
                diagnostics=_structured_diags(diags)) + "\n")
        else:
            sys.stdout.write(source)
        return 0
    except EavError as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.scaffold.v1", ok=False, status="unknown-pattern",
                pattern=args.pattern,
                diagnostics=[{"message": str(exc), "rendered": f"semanticscript: {exc}"}]) + "\n")
            return 2
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2


def cmd_fmt(args) -> int:
    """Print a program in the requested surface (canonical EAV or compact).

    Input may be either canonical EAV or compact-profile source; compact is
    expanded first, so `fmt --surface eav` canonicalizes compact and
    `fmt --surface compact` round-trips it (README ss23/ss24)."""
    src = _read_source(args.path)
    program = parse_compact(src)
    surface = getattr(args, "surface", "eav")
    role = classify_sem_file(args.path) if args.path != "-" else "source"
    formatted = (format_compact(program) if surface == "compact"
                 else format_program(program, role=role))
    if getattr(args, "check", False):
        # README §24: drift check — exit nonzero if the file is not EXACTLY
        # canonical. R-114: compare byte-for-byte (including boundary whitespace
        # and the terminal newline) so CI can't accept a file that a later `fmt`
        # or patch would churn while the check claimed the tree was clean.
        if formatted != src:
            reason = ("fmt drift — boundary whitespace / terminal newline differs"
                      if formatted.strip() == src.strip() else "fmt drift")
            sys.stderr.write(
                f"semanticscript: {reason} — run `semanticscript fmt` to canonicalize; "
                f"{_canonical_order_hint()}\n")
            return 1
        return 0
    if getattr(args, "write", False):
        if args.path == "-":
            sys.stderr.write("semanticscript: fmt -w needs a file path, not stdin\n")
            return 2
        with open(args.path, "w", encoding="utf-8", newline="") as fh:
            fh.write(formatted)
        return 0
    sys.stdout.write(formatted)
    return 0


def _fix_edits_for(diag, program) -> list:
    """Return deterministic, machine-applicable edits for one diagnostic."""
    import re

    def row_text(row: Row) -> str:
        return " ".join([row.subject, row.predicate] + list(row.payload))

    def call_entity(name: Optional[str]) -> Optional[Entity]:
        ent = program.entities.get(name or "")
        if ent and ent.kind in ("call", "task"):
            return ent
        return None

    if diag.code == "SS0803" and diag.entity:
        return [{"op": "removeEntity", "entity": diag.entity, "code": "SS0803",
                 "rationale": f"remove the unused error case {diag.entity!r}"}]
    if diag.code == "SS0807":
        binding_match = re.search(r"call binding '([^']+)'", diag.message or "")
        binding = binding_match.group(1) if binding_match else None
        for ent in program.entities.values():
            if ent.kind not in ("call", "task"):
                continue
            inv = ent.fact("invokes")
            if inv and inv.payload and inv.payload[0].startswith("assert."):
                continue
            if ent.fact("discards") is not None:
                continue
            for row in ent.facts("out"):
                if binding and (not row.payload or row.payload[0] != binding):
                    continue
                if diag.line and row.line != diag.line:
                    continue
                return [{
                    "op": "replaceRow",
                    "code": "SS0807",
                    "old": row_text(row),
                    "new": f'{ent.name} discards "unused result explicitly discarded by fix plan"',
                    "rationale": f"explicitly discard unused call binding {row.payload[0]!r}",
                }]
    if diag.code == "SS0900":
        m = re.match(r"^(\w+): declares the effect `(\S+) (\S+)` but never performs it",
                     diag.message or "")
        if m:
            op, action, resource = m.group(1), m.group(2), m.group(3)
            return [{"op": "removeRow", "code": "SS0900",
                     "row": f"{op} effect {action} {resource}",
                     "rationale": f"remove the over-declared effect "
                                  f"`{action} {resource}` from {op!r}"}]
    if diag.code == "SS1201":
        ent = call_entity(diag.entity)
        if ent is None:
            return []
        inv = ent.fact("invokes")
        if not inv or not inv.payload:
            return []
        sig = _builtin_target_signature(inv.payload[0])
        if sig is None or sig.get("variadic"):
            return []
        expected = list(sig.get("args") or [])
        arg_rows = [row for row in ent.facts("arg") if len(row.payload) >= 2]
        if len(arg_rows) != len(expected):
            return []
        expected_slots = [arg["slot"] for arg in expected]
        existing_slots = [row.payload[0] for row in arg_rows]
        missing = {slot for slot in expected_slots if slot not in existing_slots}
        unknown = [row for row in arg_rows if row.payload[0] not in expected_slots]
        if not unknown or len(unknown) != len(missing):
            return []
        edits = []
        used_new_slots = set()
        for idx, row in enumerate(arg_rows):
            if row not in unknown:
                continue
            wanted = expected[idx]
            new_slot = wanted["slot"]
            if new_slot not in missing or row.payload[1] != wanted["type"]:
                return []
            if new_slot in used_new_slots:
                return []
            used_new_slots.add(new_slot)
            new_payload = [new_slot] + list(row.payload[1:])
            edits.append({
                "op": "replaceRow",
                "code": "SS1201",
                "old": row_text(row),
                "new": " ".join([row.subject, "arg"] + new_payload),
                "rationale": (f"rename arg slot {row.payload[0]!r} to "
                              f"{new_slot!r} for {inv.payload[0]!r}"),
            })
        return edits
    # AQ-5: the style tier becomes machine-applyable. SS1340 (ifValue/ifOut is
    # comparison sugar) is repaired exactly by running the source through fmt,
    # which canonicalizes the sugar to `compare` + `branch if`. Emit a
    # whole-source `formatSource` edit so `patch` can realize the style fix.
    if diag.code == "SS1340":
        return [{"op": "formatSource", "code": "SS1340",
                 "rationale": "canonicalize ifValue/ifOut sugar to compare + "
                              "`branch if` via fmt (style-tier repair)"}]
    # R-09: a fallible call with a `catch` but no `branch ifError` (SS3501) is
    # repaired by wiring the canonical error path (the eav-fallible-operation idiom):
    # `branch ifError <call> goto <label>` after the `do`, a failure label that
    # returns a nonzero code after the normal return, and a failure-code `let` (reuse
    # an existing nonzero one if present). Scoped to an integer-resolvable out type so
    # a nonzero failure value is synthesizable; other out types stay advisory.
    if diag.code == "SS3501" and diag.entity:
        op = program.entities.get(diag.entity)
        m = re.search(r"fallible call '([^']+)'", diag.message or "")
        call_name = m.group(1) if m else None
        if op is None or op.kind not in ("operation", "function") or not call_name:
            return []
        alias_map = program.alias_map()
        out_row = op.fact("out")
        out_type = out_row.payload[0] if out_row and out_row.payload else None
        if not out_type or _resolve_alias(out_type, alias_map) not in _INT_RANGES:
            return []
        do_row = next((r for r in op.facts("do")
                       if r.payload and r.payload[0] == call_name), None)
        ret_row = next((r for r in op.facts("return")), None)
        if do_row is None or ret_row is None:
            return []
        label = f"{call_name}Failed"
        if label in {r.payload[0] for r in op.facts("at") if r.payload}:
            return []
        fail_binding = None
        for r in op.facts("let"):
            p = r.payload
            if len(p) >= 4 and _resolve_alias(p[2], alias_map) in _INT_RANGES:
                try:
                    if _parse_int_literal_value(p[3]) != 0:
                        fail_binding = p[0]
                        break
                except (ValueError, EavError):
                    pass
        edits = []
        if fail_binding is None:
            fail_binding = f"{call_name}FailCode"
            first_let = next((r for r in op.facts("let") if r.payload), None)
            if first_let is None:
                return []
            edits.append({
                "op": "replaceRow", "code": "SS3501", "old": row_text(first_let),
                "new": f"{op.name} let {fail_binding} immutable {out_type} 1\n"
                       f"{row_text(first_let)}",
                "rationale": f"add a nonzero failure code for {op.name!r}"})
        edits.append({
            "op": "replaceRow", "code": "SS3501", "old": row_text(do_row),
            "new": f"{row_text(do_row)}\n{op.name} branch ifError {call_name} goto {label}",
            "rationale": f"route {call_name!r} errors to a failure path"})
        edits.append({
            "op": "replaceRow", "code": "SS3501", "old": row_text(ret_row),
            "new": f"{row_text(ret_row)}\n{op.name} at {label} return {fail_binding}",
            "rationale": f"return the failure code on the {call_name!r} error path"})
        return edits
    return []


def _dedupe_patch_edits(edits: list) -> list:
    seen = set()
    out = []
    for edit in edits:
        key = (edit.get("op"), edit.get("entity"), edit.get("row"),
               edit.get("old"), edit.get("new"))
        if key in seen:
            continue
        seen.add(key)
        out.append(edit)
    return out


def cmd_fix(args) -> int:
    """Derive a repair plan from lint diagnostics (sem.fixPlan.v1). Blocker-first
    by default; `--include-warnings` adds cleanup guidance.

    DX-04: where a diagnostic has a deterministic, safe repair (SS0803 dead error
    case, SS0900 over-declared effect), the plan now carries machine-applicable
    `edits` and sets `planUsable: true`, so `patch` can close the loop. Everything
    else stays advisory (suggestions-only)."""
    import os
    program = parse_compact(_read_source(args.path))
    diags = lint(program)
    targeted = (diags if getattr(args, "include_warnings", False)
                else [d for d in diags if d.severity == "error"])
    items, edits = [], []
    for d in targeted:
        entry = DIAGNOSTICS.get(d.code, {})
        items.append({"code": d.code, "severity": d.severity, "line": d.line,
                      "message": d.message, "found": entry.get("found"),
                      "suggested": entry.get("suggested")})
        edits.extend(_fix_edits_for(d, program))
    edits = _dedupe_patch_edits(edits)
    plan_usable = bool(edits)
    status = ("applyable" if plan_usable
              else "suggestions-only" if items else "ok")
    sys.stdout.write(_json_envelope(
        "sem.fixPlan.v1", status=status, planUsable=plan_usable,
        path=(os.path.abspath(args.path) if args.path != "-" else "-"),
        edits=edits, diagnostics=items) + "\n")
    return 0


def cmd_patch(args) -> int:
    """Apply a repair plan (sem.patch.v1). R-016: load and validate the plan JSON
    named on the command line and honor `--dry-run`/`--apply`, instead of
    emitting a canned suggestions-only payload regardless of input. A missing or
    corrupt plan is now a distinct, reportable error — indistinguishable before
    from a valid plan. A `fix` plan is applyable only when it carries
    `planUsable:true`; suggestions-only plans are reported faithfully after a
    valid plan is actually read."""
    import json
    import os
    plan_path = getattr(args, "plan", None)
    dry_run = getattr(args, "dry_run", False)
    if not plan_path:
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="no-plan", applied=0, dryRun=dry_run,
            note="no plan file given; pass the saved `fix --json` plan "
                 "(sem.fixPlan.v1) to patch") + "\n")
        return 2
    if not os.path.isfile(plan_path):
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="missing-plan", applied=0,
            dryRun=dry_run, plan=plan_path,
            note="plan file does not exist") + "\n")
        return 2
    try:
        plan = json.loads(open(plan_path, encoding="utf-8").read())
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="corrupt-plan", applied=0,
            dryRun=dry_run, plan=plan_path,
            note=f"plan is not valid JSON: {exc}") + "\n")
        return 2
    if not isinstance(plan, dict) or plan.get("surface") != "sem.fixPlan.v1":
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="invalid-plan", applied=0,
            dryRun=dry_run, plan=plan_path,
            note="plan is not a sem.fixPlan.v1 envelope (run `fix --json`)") + "\n")
        return 2
    if not bool(plan.get("planUsable")):
        # a suggestions-only plan has no machine-applicable edits — report that
        # honestly whether the caller asked for --dry-run or --apply.
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=True, status="suggestions-only", applied=0,
            dryRun=dry_run, plan=plan_path,
            suggestions=len(plan.get("diagnostics", []) or []),
            note="plan is suggestions-only; apply the suggested repairs manually") + "\n")
        return 0
    # DX-04: apply the machine-applicable edits (removeEntity / removeRow). Edits
    # are content-addressed (matched by row/entity text, not line number), so a
    # stale plan that no longer matches fails closed instead of corrupting source.
    src_path = plan.get("path")
    if not src_path or src_path == "-" or not os.path.isfile(src_path):
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="no-source", applied=0, dryRun=dry_run,
            plan=plan_path, path=src_path,
            note="the plan's source `path` is missing/unreadable (or stdin `-`); "
                 "regenerate with `fix --json <file>`") + "\n")
        return 2
    edits = plan.get("edits", []) or []
    try:
        with open(src_path, encoding="utf-8") as fh:
            original = fh.read()
    except OSError as exc:
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="no-source", applied=0, dryRun=dry_run,
            plan=plan_path, path=src_path, note=str(exc)) + "\n")
        return 2

    remove_entities = {e["entity"] for e in edits
                       if e.get("op") == "removeEntity" and e.get("entity")}
    remove_rows = [e["row"] for e in edits if e.get("op") == "removeRow" and e.get("row")]
    replace_rows = [e for e in edits
                    if e.get("op") == "replaceRow" and e.get("old") and e.get("new")]
    # AQ-5: a whole-source style repair (canonicalize via fmt) after row edits.
    format_source = any(e.get("op") == "formatSource" for e in edits)

    def row_key(text: str) -> tuple:
        try:
            return tuple(tokenize_line(text))
        except EavError:
            return tuple(text.split())

    remove_rows_norm = {row_key(r) for r in remove_rows}
    replace_by_old = {row_key(e["old"]): e["new"] for e in replace_rows}
    pending_rows = set(remove_rows_norm)
    pending_replacements = set(replace_by_old)
    kept, dropped, replaced = [], [], []
    for line in original.split("\n"):
        toks = row_key(line)
        if toks and toks[0] in remove_entities:          # whole-entity removal
            dropped.append(line)
            continue
        key = tuple(toks)
        if key in pending_rows:                           # single-row removal (once)
            dropped.append(line)
            pending_rows.discard(key)
            continue
        if key in pending_replacements:                   # single-row replacement
            kept.append(replace_by_old[key])
            replaced.append(line)
            pending_replacements.discard(key)
            continue
        kept.append(line)
    new_source = "\n".join(kept)

    # an edit that matched nothing means the plan is stale — fail closed.
    unmatched = ([e for e in remove_entities
                  if not any(row_key(l)[:1] == (e,) for l in dropped)]
                 + [" ".join(r) for r in pending_rows]
                 + [" ".join(r) for r in pending_replacements])
    if unmatched:
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="stale-plan", applied=0, dryRun=dry_run,
            plan=plan_path, path=src_path, unmatched=sorted(unmatched),
            note="an edit no longer matches the source (it changed since `fix`); "
                 "regenerate the plan") + "\n")
        return 2

    # AQ-5: realize the style-tier repair — canonicalize the whole source through
    # fmt (the formatter *is* the fix for SS1340 sugar). Run after row edits so the
    # two compose, and before re-validation so the formatted bytes are what's vetted.
    if format_source:
        try:
            new_source = format_program(parse_compact(new_source))
        except EavError as exc:
            sys.stdout.write(_json_envelope(
                "sem.patch.v1", ok=False, status="would-break", applied=0,
                dryRun=dry_run, plan=plan_path, path=src_path,
                note=f"formatting the plan would not parse: {exc}") + "\n")
            return 2

    # re-validate the edited source before writing — never persist a broken file.
    try:
        parse_compact(new_source)
    except EavError as exc:
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=False, status="would-break", applied=0, dryRun=dry_run,
            plan=plan_path, path=src_path,
            note=f"applying the plan would not parse: {exc}") + "\n")
        return 2

    if dry_run:
        sys.stdout.write(_json_envelope(
            "sem.patch.v1", ok=True, status="dry-run", applied=0,
            wouldApply=len(edits), dryRun=True, plan=plan_path, path=src_path,
            removedLines=len(dropped), replacedLines=len(replaced)) + "\n")
        return 0
    with open(src_path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(new_source if new_source.endswith("\n") else new_source + "\n")
    sys.stdout.write(_json_envelope(
        "sem.patch.v1", ok=True, status="applied", applied=len(edits),
        dryRun=False, plan=plan_path, path=src_path,
        removedLines=len(dropped), replacedLines=len(replaced)) + "\n")
    return 0


def cmd_query(args) -> int:
    """Print the result of a structural query (`--dimension`)."""
    want_json = getattr(args, "json", False)
    try:
        program = parse_compact(_read_program_source(args.path))  # R-117/R-165: project dirs + compact
    except EavError as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.query.v1", status="compiler-error", ok=False,
                diagnostics=[f"semanticscript: {exc}"]) + "\n")
            return 1
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2
    if args.dimension not in QUERY_DIMENSIONS:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.query.v1", status="tool-error", ok=False,
                message=f"unknown query dimension {args.dimension!r}",
                dimensions=sorted(QUERY_DIMENSIONS)) + "\n")
            return 2
        sys.stderr.write(
            f"semanticscript: unknown query dimension {args.dimension!r}; choose from "
            f"{', '.join(QUERY_DIMENSIONS)}\n"
        )
        return 2
    results = list(query(program, args.dimension))
    if want_json:
        sys.stdout.write(_json_envelope(
            "sem.query.v1", status="ok", dimension=args.dimension,
            results=results) + "\n")
    else:
        for line in results:
            sys.stdout.write(line + "\n")
    return 0


def cmd_rename(args) -> int:
    """Rename an entity and all references; print the updated source."""
    import os
    try:
        if args.path != "-" and os.path.isdir(args.path):
            rewritten = rename_project_sources(args.path, args.old, args.new)
            if getattr(args, "write", False):
                for path in sorted(rewritten):
                    _atomic_write_text(path, rewritten[path])
                sys.stdout.write(
                    f"renamed {args.old!r} to {args.new!r} in {len(rewritten)} file(s)\n")
            else:
                sys.stdout.write("\n".join(rewritten[p] for p in sorted(rewritten)))
                if rewritten:
                    sys.stdout.write("\n")
            return 0
        out = rename_entity(_read_source(args.path), args.old, args.new)
        if getattr(args, "write", False):
            if args.path == "-":
                raise EavError("rename --write requires a filesystem path, not stdin")
            _atomic_write_text(args.path, out)
            sys.stdout.write(f"renamed {args.old!r} to {args.new!r} in {args.path}\n")
        else:
            sys.stdout.write(out)
        return 0
    except EavError as exc:
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2


def cmd_add(args) -> int:
    """Append a scaffolded operation; print the updated source."""
    try:
        sys.stdout.write(add_operation(_read_source(args.path), args.name, args.out))
        return 0
    except EavError as exc:
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2


def cmd_pack(args) -> int:
    """Print a budgeted context bundle for editing an entity."""
    program = parse_compact(_read_program_source(args.path))
    try:
        if getattr(args, "json", False):
            sys.stdout.write(_json_envelope(
                "sem.pack.v1", status="ok",
                **pack_details(program, args.entity, args.budget)) + "\n")
        else:
            sys.stdout.write(pack(program, args.entity, args.budget) + "\n")
        return 0
    except EavError as exc:
        if getattr(args, "json", False):
            sys.stdout.write(_json_envelope(
                "sem.pack.v1", ok=False, status="not-found", entity=args.entity,
                diagnostics=[{"message": str(exc), "rendered": f"semanticscript: {exc}"}]) + "\n")
            return 2
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2


def cmd_slice(args) -> int:
    """Print the semantic slice of an entity (sem.slice.v1 with --json)."""
    want_json = getattr(args, "json", False) or getattr(args, "format", "canonical") == "json"
    try:
        program = parse_compact(_read_program_source(args.path))
    except EavError as exc:
        if getattr(args, "json", False):
            raise
        if want_json:
            diag = {"code": getattr(exc, "code", None), "severity": "error",
                    "line": getattr(exc, "line", None),
                    "message": getattr(exc, "message", str(exc)),
                    "rendered": f"semanticscript: {exc}"}
            sys.stdout.write(_json_envelope(
                "sem.slice.v1", ok=False, status="compiler-error",
                entity=args.entity, diagnostics=[diag]) + "\n")
            return 2
        raise
    try:
        text = slice_entity(program, args.entity, path_filter=getattr(args, "path_filter", None))
    except EavError as exc:
        if want_json:
            diag = {"code": getattr(exc, "code", None), "severity": "error",
                    "line": getattr(exc, "line", None),
                    "message": getattr(exc, "message", str(exc)),
                    "rendered": f"semanticscript: {exc}"}
            sys.stdout.write(_json_envelope(
                "sem.slice.v1", ok=False, status="not-found",
                entity=args.entity, diagnostics=[diag]) + "\n")
        else:
            sys.stderr.write(f"semanticscript: {exc}\n")
        return 2
    if want_json:
        sys.stdout.write(_json_envelope(
            "sem.slice.v1",
            **slice_details(
                program,
                args.entity,
                refs=getattr(args, "refs", False),
                for_edit=getattr(args, "for_edit", False),
                path_filter=getattr(args, "path_filter", None),
            )) + "\n")
    elif getattr(args, "format", "canonical") == "prompt":
        details = slice_details(
            program, args.entity, refs=True, for_edit=True,
            path_filter=getattr(args, "path_filter", None))
        sys.stdout.write(details["prompt"])
    else:
        sys.stdout.write(text)
    return 0


def cmd_test(args) -> int:
    """Discover (--discover) or execute `tag test` operations (sem.test.v1).

    R-007: when the path is a project directory, compose the runtime program with
    its companion `*.test.sem` sources (`load_test_project`) so co-located test
    operations are actually executed — `load_project` alone excludes test files,
    so a scaffold's `checkGreetingLength` would otherwise never run.

    WS2-071: --strict blocks T3 warnings before running tests."""
    import os
    try:
        if (args.path != "-" and os.path.isdir(args.path)
                and is_project_root(args.path)):
            program = load_test_project(args.path)
        else:
            program = parse_compact(_read_program_source(args.path))
    except EavError as exc:
        sys.stdout.write(_json_envelope(
            "sem.test.v1", ok=False, status="compiler-error",
            preflightStatus="compiler-error", runtimeHarnessStatus="not-run",
            compositeStatus="blocked", tests=[], diagnostics=[str(exc)]) + "\n")
        return 1
    # WS2-071: --strict blocks T3 warnings
    if getattr(args, "strict", False):
        diags = lint(program)
        diags = _filter_diagnostics_strict(diags, True)
        errors = [d for d in diags if d.severity == "error"]
        if errors:
            sys.stdout.write(_json_envelope(
                "sem.test.v1", ok=False, status="lint-error",
                preflightStatus="lint-error", runtimeHarnessStatus="not-run",
                compositeStatus="blocked", tests=[],
                diagnostics=[d.render() for d in errors]) + "\n")
            return 1
    if getattr(args, "discover", False):
        lanes = discover_tests(program)
        selected = {args.lane: lanes.get(args.lane, [])} if args.lane else lanes
        total = 0
        for lane in selected:
            total += len(selected[lane])
        if getattr(args, "json", False):
            sys.stdout.write(_json_envelope(
                "sem.test.v1", status="discovered",
                selectedLane=args.lane, lanes=selected,
                totalCount=total) + "\n")
            return 0
        for lane in sorted(selected):
            for op in selected[lane]:
                sys.stdout.write(f"{lane}: {op}\n")
        sys.stdout.write(f"{total} test operation(s)\n")
        return 0
    report = run_tests(program, lane=getattr(args, "lane", None))
    # R-102: only a clean `pass` is ok — a lint-`blocked` preflight, an error, or
    # a failing test is ok:false so an envelope consumer can't read a blocked run
    # as success (the process exit already distinguishes pass from not-pass).
    # R-158: a selected lane that found zero tests is `no-tests` (ok:false) unless
    # the caller opts in with --allow-empty.
    composite = report["compositeStatus"]
    ok = composite == "pass" or (composite == "no-tests"
                                 and getattr(args, "allow_empty", False))
    sys.stdout.write(_json_envelope("sem.test.v1", ok=ok, **report) + "\n")
    return 0 if ok else 1


def cmd_doctor(args) -> int:
    """Print a severity-grouped diagnostic report with suggested fixes."""
    program = parse_compact(_read_program_source(args.path))
    groups = doctor(program)
    total = sum(len(v) for v in groups.values())
    for severity in ("error", "warning", "info"):
        for d in groups.get(severity, []):
            sys.stdout.write(d.render() + "\n")
            if severity == "error" and d.code in DIAGNOSTICS:
                sys.stdout.write("    " + DIAGNOSTICS[d.code]["suggested"] + "\n")
            add_argv = _doctor_suggested_add_argv(program, args.path, d)
            if add_argv:
                import json
                sys.stdout.write("    Suggested sem add argv: "
                                 + json.dumps(add_argv) + "\n")
    if total == 0:
        sys.stdout.write("healthy: no diagnostics\n")
    return 1 if groups.get("error") else 0


def cmd_inventory(args) -> int:
    """Print entity counts by kind."""
    # ERG-2: an analysis command (like summary/graph/symbols/context/size) accepts a
    # project DIRECTORY, not only a single file - route through the dir-aware,
    # compact-aware loader so `inventory <project>` works like its peers.
    program = parse_compact(_read_program_source(args.path))
    counts = summarize(program)
    for kind in sorted(counts):
        sys.stdout.write(f"{counts[kind]:4d}  {kind}\n")
    sys.stdout.write(f"{sum(counts.values()):4d}  total\n")
    return 0


def cmd_lint(args) -> int:
    """Lint a program: print all MD/lint diagnostics; exit 1 if any are errors.
    With `--explain CODE`, print the registry rationale + required pattern."""
    if getattr(args, "explain", None):
        try:
            sys.stdout.write(format_repair(args.explain) + "\n")
            return 0
        except EavError as exc:
            sys.stderr.write(f"semanticscript: {exc}\n")
            return 2
    output_format = getattr(args, "format", None)
    want_json = bool(getattr(args, "json", False) or output_format == "json")
    codes = list(getattr(args, "code", None) or [])
    tiers = list(getattr(args, "tier", None) or [])
    try:
        for code in codes:
            explain(code)
    except EavError as exc:
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.lint.v1", status="tool-error", ok=False,
                diagnostics=[{"code": None, "severity": "error", "line": None,
                              "entity": None, "message": exc.message,
                              "rendered": f"semanticscript: {exc}",
                              "tier": None, "confidence": "high",
                              "effort": "trivial"}]) + "\n")
            return 2
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2
    try:
        program = parse_compact(_read_program_source(args.path))
    except EavError as exc:
        # R-085: a parse error on `lint --json` must still be a versioned
        # `sem.lint.v1` envelope (never plaintext), so MCP/agent consumers can
        # distinguish compiler-error from lint-diagnostics.
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.lint.v1", status="compiler-error", ok=False,
                diagnostics=[{"code": exc.code, "severity": "error",
                              "line": exc.line, "entity": None,
                              "message": exc.message,
                              "rendered": f"semanticscript: {exc}",
                              "tier": explain(exc.code).get("tier") if exc.code in DIAGNOSTICS else None,
                              "confidence": "high", "effort": "local"}]) + "\n")
            return 1
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2
    diags = _filter_diagnostics_for_cli(lint(program), tiers=tiers, codes=codes)
    errors = [d for d in diags if d.severity == "error"]
    warnings = [d for d in diags if d.severity == "warning"]
    if want_json:
        # R-085: success is a `sem.*.v1` envelope with structured diagnostics,
        # not the legacy bare array.
        status = ("lint-diagnostics" if errors
                  else "ok-with-warnings" if warnings else "ok")
        sys.stdout.write(_json_envelope(
            "sem.lint.v1", status=status,
            ok=(status in ("ok", "ok-with-warnings")),
            diagnostics=_structured_diags(diags)) + "\n")
    else:
        for d in diags:
            sys.stdout.write(d.render() + "\n")
            sys.stdout.write(format_repair(d.code) + "\n")
        if not diags:
            sys.stdout.write("no lint diagnostics\n")
    return 1 if errors else 0


def cmd_reserved_words(args) -> int:
    """Print the parser's reserved-word table."""
    words = sorted(RESERVED_WORDS)
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope(
            "sem.reservedWords.v1", status="ok", words=words,
            futureReserved=sorted(RESERVED_FUTURE)) + "\n")
    else:
        for word in words:
            sys.stdout.write(word + "\n")
    return 0


def cmd_targets(args) -> int:
    """A9/S1: list the concrete call targets the LLVM console code generator
    models as the public runnable vocabulary. Every advertised target has a real
    signature, and target rows carry the stdlib maturity label (`proven` or
    `experimental`) so broad implementation prefixes are not mistaken for stable
    call contracts.

    DX-08: `targets --signature <target>` returns one built-in's declared signature
    (arg slot names + types + out) from standard.<module>.semsig or the generated
    codegen fallback, so an agent can look up e.g. math.divideInt64's `left`/`right`
    slots instead of guessing."""
    want_json = getattr(args, "json", False)
    sig_target = getattr(args, "signature", None)
    if sig_target:
        family_sigs = _builtin_family_signatures(sig_target)
        if family_sigs:
            if want_json:
                enriched = [_signature_with_maturity(sig) for sig in family_sigs]
                sys.stdout.write(_json_envelope(
                    "sem.targetSignatures.v1", ok=True, status="ok",
                    target=sig_target, count=len(enriched),
                    signatures=enriched) + "\n")
            else:
                print(sig_target)
                for sig in family_sigs:
                    print(f"  {sig['target']}")
                    for a in sig["args"]:
                        print(f"    arg {a['slot']} {a['type']}")
                    if sig["out"]:
                        out_slot = (sig["outSlot"] + " ") if sig["outSlot"] else ""
                        print(f"    out {out_slot}{sig['out']}")
                    if sig.get("purpose"):
                        print(f"    purpose \"{sig['purpose']}\"")
            return 0
        sig = _builtin_target_signature(sig_target)
        if sig is None:
            if want_json:
                sys.stdout.write(_json_envelope(
                    "sem.targetSignature.v1", ok=False, status="unknown-target",
                    target=sig_target,
                    note="no signature for this target; run `targets` for the "
                         "modeled vocabulary") + "\n")
            else:
                sys.stderr.write(
                    f"semanticscript: no signature for target {sig_target!r} "
                    f"(run `targets` to list the modeled vocabulary)\n")
            return 2
        if want_json:
            sys.stdout.write(_json_envelope(
                "sem.targetSignature.v1", ok=True, status="ok",
                **_signature_with_maturity(sig)) + "\n")
        else:
            print(sig["target"])
            for a in sig["args"]:
                print(f"  arg {a['slot']} {a['type']}")
            if sig["out"]:
                print(f"  out {(sig['outSlot'] + ' ') if sig['outSlot'] else ''}{sig['out']}")
            if sig.get("purpose"):
                print(f"  purpose \"{sig['purpose']}\"")
        return 0
    catalog = _target_catalog()
    if want_json:
        import json
        print(json.dumps({
            "surface": "sem.targets.v1",
            "version": "sem.targets.v1",
            "families": {f: sorted(v) for f, v in sorted(catalog["families"].items())},
            "familyStatus": catalog["familyStatus"],
            "targets": catalog["targets"],
        }, indent=2))
    else:
        for fam in sorted(catalog["families"]):
            status = catalog["familyStatus"].get(fam, {})
            suffix = " (experimental)" if status.get("experimental") else ""
            print(f"{fam}{suffix}:")
            for t in sorted(catalog["families"][fam]):
                print(f"  {t}")
    return 0


def cmd_explain(args) -> int:
    """Print the registry entry + repair for a diagnostic code."""
    try:
        sys.stdout.write(format_repair(args.code) + "\n")
        return 0
    except EavError as exc:
        sys.stderr.write(f"semanticscript: {exc}\n")
        return 2


def _read_source(path: str) -> str:
    if path == "-":
        return sys.stdin.read()
    try:
        with open(path, encoding="utf-8") as fh:
            return fh.read()
    except OSError as exc:
        # R-001: turn a directory/unreadable-path OSError (e.g. PermissionError or
        # IsADirectoryError on a project dir) into an EavError so `main` reports a
        # stable `semanticscript: …` message and exit 2 instead of a raw Python traceback.
        import os
        if os.path.isdir(path):
            raise EavError(
                f"{path!r} is a directory; this command reads a single file — "
                f"pass a .sem file, or use a project-aware command (README ss24)")
        raise EavError(f"cannot read {path!r}: {exc.strerror or exc}")


def _program_summary(program: Program) -> dict:
    """AQ-11: a first-class structured whole-program semantic summary - one envelope
    aggregating what was scattered across inventory/context/symbols/graph: entity
    counts by kind, every operation with its effects/capabilities/invoked targets,
    the declared capabilities + grants, the effect set, and the call-graph edges."""
    from collections import Counter
    kinds = Counter(e.kind for e in program.entities.values())
    ops, edges, effects, caps = [], [], set(), []
    # index calls by owning op once
    owner_calls = {}
    for c in program.order:
        ce = program.entities[c]
        if ce.kind in ("call", "task"):
            owner = ce.fact("in")
            inv = ce.fact("invokes")
            if owner and owner.payload and inv and inv.payload:
                owner_calls.setdefault(owner.payload[0], []).append(inv.payload[0])
    for n in program.order:
        ent = program.entities[n]
        if ent.kind in ("operation", "function"):
            op_effects = [" ".join(r.payload) for r in ent.facts("effect") if r.payload]
            uses = [r.payload[0] for r in ent.facts("uses") if r.payload]
            invoked = sorted(set(owner_calls.get(ent.name, [])))
            for tgt in invoked:
                edges.append({"from": ent.name, "to": tgt})
            effects.update(op_effects)
            ops.append({"name": ent.name, "effects": op_effects,
                        "uses": uses, "invokes": invoked})
        elif ent.kind == "capability":
            caps.append({"name": ent.name,
                         "grants": [" ".join(g.payload) for g in ent.facts("grants") if g.payload]})
    return {
        "target": _program_target(program),
        "entityCounts": dict(sorted(kinds.items())),
        "operations": ops,
        "capabilities": caps,
        "effects": sorted(effects),
        "callGraph": edges,
    }


def cmd_summary(args) -> int:
    """AQ-11: emit a structured whole-program semantic summary (sem.summary.v1)."""
    program = parse_compact(_read_program_source(args.path))
    summary = _program_summary(program)
    if getattr(args, "json", False):
        sys.stdout.write(_json_envelope("sem.summary.v1", ok=True, **summary) + "\n")
    else:
        sys.stdout.write(f"target: {summary['target']}\n")
        sys.stdout.write("entities: " + ", ".join(
            f"{k}={v}" for k, v in summary["entityCounts"].items()) + "\n")
        sys.stdout.write(
            f"operations: {len(summary['operations'])}, effects: "
            f"{len(summary['effects'])}, capabilities: {len(summary['capabilities'])}, "
            f"call-edges: {len(summary['callGraph'])}\n")
    return 0


def main(argv: Optional[list[str]] = None) -> int:
    # EAV source and output are UTF-8 (README §33.2). On Windows the default
    # console encoding is cp1252, which cannot encode characters that legitimately
    # appear in source (em-dashes in comments, Unicode string literals) and would
    # crash `fmt`/`run` output or corrupt a `fmt -` stdin pipe; force UTF-8 on
    # every standard stream so source round-trips through pipes intact.
    for _stream in (sys.stdin, sys.stdout, sys.stderr):
        try:
            if _stream is sys.stdin:
                _stream.reconfigure(encoding="utf-8")
            else:
                _stream.reconfigure(encoding="utf-8", errors="backslashreplace")
        except (AttributeError, ValueError):
            pass
    parser = argparse.ArgumentParser(
        prog="semanticscript", description="EAV-Steps front end (lex/parse/lower/run)"
    )
    sub = parser.add_subparsers(dest="command", required=True)

    for name, fn in (
        ("lex", cmd_lex),
        ("parse", cmd_parse),
        ("lower", cmd_lower),
        ("inventory", cmd_inventory),
        ("doctor", cmd_doctor),
    ):
        sp = sub.add_parser(name)
        sp.add_argument("path", help="EAV source file, or - for stdin")
        sp.set_defaults(func=fn)

    # TOOL-3: IR inspection — emit-ir (optionally optimized, -o aware) + inspect-ir
    sp_emit = sub.add_parser("emit-ir", help="emit textual LLVM IR (optionally optimized)")
    sp_emit.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_emit.add_argument("--optimized", action="store_true", help="run LLVM -O2 passes")
    sp_emit.add_argument("--output", "-o", help="write IR to this path instead of stdout")
    sp_emit.set_defaults(func=cmd_emit_ir)
    sp_inspect = sub.add_parser("inspect-ir", help="structured summary of the lowered module")
    sp_inspect.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_inspect.add_argument("--json", action="store_true")
    sp_inspect.set_defaults(func=cmd_inspect_ir)
    # AQ-11: first-class whole-program semantic summary
    sp_summary = sub.add_parser("summary", help="structured whole-program semantic summary (entities, effects, capabilities, call graph)")
    sp_summary.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_summary.add_argument("--json", action="store_true")
    sp_summary.set_defaults(func=cmd_summary)

    # TOOL-4: toolchain self-diagnostic + cache clean
    sp_status = sub.add_parser("status", help="toolchain self-diagnostic (versions, C toolchain, cache, platform)")
    sp_status.add_argument("--json", action="store_true")
    sp_status.set_defaults(func=cmd_status)
    sp_clean = sub.add_parser("clean", help="clear the cached native runtime/build artifacts")
    sp_clean.add_argument("--json", action="store_true")
    sp_clean.set_defaults(func=cmd_clean)

    # TOOL-5: diagnostic-code catalog + keyword search
    sp_index = sub.add_parser("index", help="catalog every diagnostic code (tier + summary)")
    sp_index.add_argument("--json", action="store_true")
    sp_index.set_defaults(func=cmd_index)
    sp_reserved = sub.add_parser("reserved-words", help="list reserved words from the parser table")
    sp_reserved.add_argument("--json", action="store_true")
    sp_reserved.set_defaults(func=cmd_reserved_words)
    sp_targets = sub.add_parser("targets", help="list the runnable/codegen-modeled call targets (the vocabulary run/build can lower)")
    sp_targets.add_argument("--json", action="store_true")
    sp_targets.add_argument("--signature", metavar="TARGET",
                            help="show one built-in target's arg slots/types + out (DX-08)")
    sp_targets.set_defaults(func=cmd_targets)
    sp_search = sub.add_parser("search", help="relevance-ranked retrieval across docs/diagnostics/skills/templates/spec")
    sp_search.add_argument("query", help="search terms")
    sp_search.add_argument("--source", nargs="*",
                           choices=["diagnostic", "target", "skill", "template", "rules", "spec", "entity"],
                           help="restrict to these corpus sources")
    sp_search.add_argument("--path", help="include this project's entities in the corpus")
    sp_search.add_argument("--limit", type=int, default=20, help="max results (default 20)")
    sp_search.add_argument("--json", action="store_true")
    sp_search.set_defaults(func=cmd_search)

    # TOOL-6: pipeline benchmark
    sp_bench = sub.add_parser("bench", help="benchmark parse/lower/JIT-run (best of N)")
    sp_bench.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_bench.add_argument("--runs", type=int, default=5, help="iterations (default 5)")
    sp_bench.add_argument("--json", action="store_true")
    sp_bench.set_defaults(func=cmd_bench)

    # R-057: performance/IR baseline (sem.profile.v1)
    sp_profile = sub.add_parser("profile", help="IR-quality + parse/lower timing baseline (sem.profile.v1)")
    sp_profile.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_profile.add_argument("--runs", type=int, default=5, help="iterations (default 5)")
    sp_profile.add_argument("--json", action="store_true")
    sp_profile.set_defaults(func=cmd_profile)

    # R-047/R-081: dependency workflow commands. Remote registry fetch is still
    # out of scope; these operate on build.sem plus replacement, module-cache,
    # and vendored artifacts.
    sp_get = sub.add_parser("get", help="add or upgrade a build.sem dependency requirement")
    sp_get.add_argument("dependency", help="dependency spec repo/path@vMAJOR.MINOR.PATCH")
    sp_get.add_argument("path", nargs="?", default=".", help="project directory or build.sem manifest")
    sp_get.add_argument("--json", action="store_true")
    sp_get.set_defaults(func=cmd_get)

    sp_mod = sub.add_parser("mod", help="module dependency commands")
    mod_sub = sp_mod.add_subparsers(dest="mod_command", required=True)
    sp_mod_tidy = mod_sub.add_parser("tidy", help="resolve and write build.sem.lock")
    sp_mod_tidy.add_argument("path", nargs="?", default=".", help="project directory or build.sem manifest")
    sp_mod_tidy.add_argument("--check", action="store_true", help="verify the lock is current, do not write")
    sp_mod_tidy.add_argument("--json", action="store_true")
    sp_mod_tidy.set_defaults(func=cmd_mod)

    sp_vendor = sub.add_parser("vendor", help="materialize replacement/cache dependencies under vendor/")
    sp_vendor.add_argument("path", nargs="?", default=".", help="project directory or build.sem manifest")
    sp_vendor.add_argument("--json", action="store_true")
    sp_vendor.set_defaults(func=cmd_vendor)

    # TOOL-7: re-pin dependencies (regenerate build.sem.lock via MVS)
    sp_repin = sub.add_parser("repin", help="regenerate build.sem.lock from build.sem (MVS)")
    sp_repin.add_argument("path", help="project directory or build.sem manifest")
    sp_repin.add_argument("--check", action="store_true", help="verify the lock is current, do not write")
    sp_repin.add_argument("--json", action="store_true")
    sp_repin.set_defaults(func=cmd_repin)

    # run needs --strict flag (WS2-071)
    sp_run = sub.add_parser("run", help="JIT-compile and execute")
    sp_run.add_argument("path", help="EAV source file, or - for stdin")
    sp_run.add_argument("--strict", action="store_true",
                        help="block T3 opinionated warnings (in addition to T0/T1/T2)")
    sp_run.add_argument("--json", action="store_true")
    sp_run.add_argument("--entry", default=None,
                        help="run a named operation as the entry (used by the "
                             "isolated test runner, R-102)")
    sp_run.add_argument("--_jit-child", dest="jit_child", action="store_true",
                        help=argparse.SUPPRESS)  # R-088: internal isolated JIT child
    sp_run.set_defaults(func=cmd_run)

    sp_effect_sandbox = sub.add_parser(
        "effect-sandbox",
        help="derive/enforce the WS2 runtime effect sandbox policy",
    )
    sp_effect_sandbox.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_effect_sandbox.add_argument("--entry", default=None,
                                   help="operation to use as the policy root")
    sp_effect_sandbox.add_argument("--strict", action="store_true",
                                   help="block T3 opinionated warnings before policy emission")
    sp_effect_sandbox.add_argument("--json", action="store_true")
    sp_effect_sandbox.set_defaults(func=cmd_effect_sandbox)

    for cname, cfn, chelp in (
        ("deps", cmd_deps, "dependency graph (imports + require)"),
        ("context", cmd_context, "project envelope"),
        ("symbols", cmd_symbols, "full entity graph"),
        ("size", cmd_size, "cheap footprint probe"),
        ("dev", cmd_dev, "one dev check+runnability tick"),
    ):
        sp = sub.add_parser(cname, help=chelp)
        sp.add_argument("path", help="EAV/compact source file, or - for stdin")
        sp.add_argument("--json", action="store_true")
        sp.set_defaults(func=cfn)

    sp_devx = sub.add_parser(
        "devx",
        help="DEVX-NEXT structured authoring/contracts/mock/diff/authority surface",
    )
    sp_devx.add_argument("path", help="SemanticScript source file or project directory")
    sp_devx.add_argument("--mode", choices=DEVX_MODES, default="all")
    sp_devx.add_argument("--focus", help="entity to enumerate legal next moves for")
    sp_devx.add_argument("--intent", help="natural-language intent for row synthesis")
    sp_devx.add_argument("--compare", help="new path for --mode diff")
    sp_devx.add_argument("--record-replay", action="store_true",
                         help="run capturedOutputReplay when --mode mock")
    sp_devx.add_argument("--json", action="store_true")
    sp_devx.set_defaults(func=cmd_devx)

    sp_compensate = sub.add_parser(
        "compensate",
        help="COMPENSATE failure-mitigation surface for agent inner loops",
    )
    sp_compensate.add_argument("path", help="SemanticScript source file or project directory")
    sp_compensate.add_argument("--mode", choices=COMP_MODES, default="all")
    sp_compensate.add_argument("--query", help="natural-language query for ranked alternatives")
    sp_compensate.add_argument("--attempt", action="append", default=[],
                               help="record a failed attempt for stuck-signal analysis")
    sp_compensate.add_argument("--compare", help="old path for semantic checkpoint comparison")
    sp_compensate.add_argument("--port", type=int, help="localhost port to probe")
    sp_compensate.add_argument("--checkpoint-dir", help="directory for checkpoint writes")
    sp_compensate.add_argument("--write-checkpoint", action="store_true",
                               help="write the current semantic checkpoint")
    sp_compensate.add_argument("--write-memory", action="store_true",
                               help="write .semanticscript/idioms.json")
    sp_compensate.add_argument("--json", action="store_true")
    sp_compensate.set_defaults(func=cmd_compensate)

    sp_docs = sub.add_parser("docs", help="docs catalog (list/get/search)")
    sp_docs.add_argument("path", nargs="?", help="EAV/compact source file, or - for stdin")
    sp_docs.add_argument("extra", nargs="*",
                         help="for persistent modes: index <path> or search <query...>")
    sp_docs.add_argument("--search", help="keyword-ranked search query")
    sp_docs.add_argument("--get", help="entity name to fetch")
    sp_docs.add_argument("--db", help="persistent docs index SQLite database")
    sp_docs.add_argument("--scope", help="restrict persistent docs search to this path")
    sp_docs.add_argument("--limit", type=int, default=10)
    sp_docs.add_argument("--json", action="store_true")
    sp_docs.set_defaults(func=cmd_docs)

    sp_eval = sub.add_parser("eval", help="JIT-run a snippet (auto-wrapped)")
    sp_eval.add_argument("path", help="EAV snippet/program file, or - for stdin")
    sp_eval.add_argument("--strict", action="store_true",
                         help="block T3 opinionated warnings (in addition to T0/T1/T2)")
    sp_eval.add_argument("--json", action="store_true")
    sp_eval.set_defaults(func=cmd_eval)

    sp_check = sub.add_parser("check", help="source lane: parse + lint status")
    sp_check.add_argument("path", help="EAV/compact source file, or - for stdin")
    sp_check.add_argument("--json", action="store_true")
    sp_check.add_argument("--strict", action="store_true",
                          help="block T3 opinionated warnings (in addition to T0/T1/T2)")
    sp_check.set_defaults(func=cmd_check)

    sp_verify_one = sub.add_parser("verify", help="one-shot check + test + run gate")
    sp_verify_one.add_argument("path", help="EAV/compact source file or project, or - for stdin")
    sp_verify_one.add_argument("--strict", action="store_true",
                               help="block T3 opinionated warnings before runtime lanes")
    sp_verify_one.add_argument("--json", action="store_true")
    sp_verify_one.add_argument("--watch", action="store_true",
                               help="rerun verify when source/test files change")
    sp_verify_one.add_argument("--watch-interval", type=float, default=1.0,
                               help="poll interval for --watch in seconds (default 1.0)")
    sp_verify_one.add_argument("--watch-count", type=int, default=None,
                               help=argparse.SUPPRESS)
    sp_verify_one.set_defaults(func=cmd_verify)

    sp_readiness = sub.add_parser("readiness", help="environment lane: toolchain status")
    sp_readiness.add_argument("--json", action="store_true")
    sp_readiness.set_defaults(func=cmd_readiness)

    sp_stdlib = sub.add_parser("stdlib-readiness",
                               help="stdlib module maturity ledger (WS3-110)")
    sp_stdlib.add_argument("--json", action="store_true")
    sp_stdlib.add_argument("--tier", choices=("core", "secondary"), default=None,
                           help="filter the displayed inventory by importance tier "
                                "(WS3-120); the gate still covers the full platform")
    sp_stdlib.set_defaults(func=cmd_stdlib_readiness)

    sp_mcp = sub.add_parser("mcp", help="run the MCP stdio JSON-RPC server")
    sp_mcp.set_defaults(func=cmd_mcp)

    sp_new = sub.add_parser("new", help="scaffold a canonical EAV project tree")
    sp_new.add_argument("path", help="project root directory to create")
    sp_new.add_argument("--enable-docs-index", action="store_true")
    sp_new.add_argument("--force", action="store_true",
                        help="overwrite existing scaffold files (default: refuse)")
    sp_new.add_argument("--json", action="store_true")
    sp_new.set_defaults(func=cmd_new)

    sp_task = sub.add_parser("task", help="emit an agent workflow checklist")
    sp_task.add_argument("template", nargs="?",
                         help="one of: " + ", ".join(sorted(EAV_TASK_TEMPLATES))
                         + " (omit to list templates)")
    sp_task.add_argument("--json", action="store_true")
    sp_task.set_defaults(func=cmd_task)

    sp_version = sub.add_parser("version", help="emit the contract version surface")
